programs.sol:
"""A lexical web/net detector, not a detector of the surrounding topic.

'Web', 'internet', and Chinese 网/網 produce large negative predictions;
network, online, grids, websites, URLs and Internet-service names produce
smaller ones. Thus a spider web or fishing net also qualifies. The constants
approximate training averages. Capitalization and leading spaces distinguish
whole-word tokens from word pieces. Other vocabulary is predicted as zero;
weak, idiosyncratic token responses and contextual variations are omitted.
"""

READS = ()

# Meaningful word families, with typical activation strengths.
FAMILIES = (
    (-1.35, 'grid grids mesh'),                         # grid structures
    (-1.1, 'blog blogs blogging cyber url urls urllib urlparse'),
    (-0.8, 'facebook youtube github wiki linkedin iot'),
    (-1.0, 'twitter netflix reddit yahoo wifi'),         # online services
    (-0.5, 'instagram html htm portal'),
    (-1.6, 'subnet ethernet'),                          # computer networks
    (-0.85, 'media 媒体 媒體 新媒体'),                   # media
    (-0.45, 'site sites'),
    (-1.2, 'www'),
    (-5.6, '互联网'),                                  # Internet
    (-4.1, 'интернет'),
    (-3.85, 'インターネット'),
    (-3.4, 'الانترنت الإنترنت'),
    (-2.5, 'ネット'),                                  # Japanese: net
    (-1.3, 'сайт сайте сет сети réseau mạng netz'),  # site/network
    (-0.8, 'онлайн ブログ サイト 在线'),  # online/blog/site
    (-6.2, '网上 網上'),                               # on the net
    (-4.8, '上网 上網 在网上'),                         # going online
    (-7.2, '本网 本網'),                               # this website
    (-2.1, '官网 官網 网址 網站 网站 官方网站 本站'),
    (-3.6, '网友 網友 有网友 网民'),                    # net users
    (-1.5, '网红 网通 网约 网约车 物联网'),              # net compounds
)
WORDS = {word: value for value, words in FAMILIES for word in words.split()}


def lexical_value(token):
    raw = token.strip()
    stem = raw.lstrip('._/-("\\')
    word = stem.lower()
    spaced = token[:1].isspace()
    capital = stem[:1].isupper()
    if word in {'web', 'webs'}:
        value = -6.4 if capital else (-5.9 if spaced else -5.3)
        if stem.isupper():
            value = -5.9 if spaced else -4.1
        if raw.startswith(('.', '/')):
            value += 1.1
        return value + (0.3 if word == 'webs' else 0.0)
    if word == 'internet':
        return (-6.3 if capital else -5.7) if spaced else -5.1
    if word in {'net', 'nets'}:
        if word == 'nets':
            return -1.8 if spaced else -1.3
        if spaced or raw.startswith('.'):
            return -2.6
        return -1.6 if stem.isupper() else (-2.2 if capital else -1.6)
    if word in {'network', 'networks', 'networking'}:
        if word != 'network':
            return -1.6 if word == 'networks' else -1.1
        return -2.0 if spaced else (-1.8 if capital else -1.3)
    if word == 'online':
        if stem.isupper():
            return -1.55
        if capital:
            return -2.3
        return -1.9 if spaced else -1.5
    if word in {'website', 'websites'}:
        return (-2.0 if spaced else -1.5) + (0.2 if word.endswith('s') else 0.0)
    if word in {'wikipedia', 'ikipedia'}:
        return 0.0 if raw.startswith('.') else -1.5
    if word.startswith('web'):
        return -1.2
    if word == 'http':
        return -0.9 if capital else -0.55
    if word == 'https':
        return -0.1
    if token == '://':
        return -1.35
    if raw.startswith('.') and word in {'com', 'org', 'gov', 'io'}:
        return -0.5 if word in {'org', 'io'} else -1.15
    if word in {'网', '網'}:
        return -7.6 if word == '网' else -8.5
    if '网' in word or '網' in word:
        return WORDS.get(word, -3.1)
    return WORDS.get(word, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # Byte fragments can finish a net character; never join across documents.
    if token == '�' and len(prefix.token_ids) > 1:
        same_doc = all(d == prefix.document_ids[-1]
                       for d in prefix.document_ids[-3:])
        if same_doc and prefix.token_strings[-2].endswith('�'):
            if prefix.text_prefixes[-1].endswith(('网', '網')):
                return None, -10.1
    return None, float(lexical_value(token))

programs.luna:
"""Predict a negative response to web, internet, and network vocabulary.

The strongest responses are to “web” and “internet”; related networking,
website, URL, and online-service words receive smaller responses.
"""

READS = ()

STRONG = {"web", "internet", "网"}
NETWORK = {
    "network", "networks", "-network", "online", "website", "websites",
    "grid", ".grid", "在线", "官网",
}
URLS = {
    "url", "urls", "http", "https", "://", ".com", ".net", ".org",
    ".io", ".html", ".github", "www",
}
SERVICES = {
    "facebook", "instagram", "blog", "wiki", "vpn", "wordpress",
    "сервис",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in STRONG:
        value = -5.8
    elif word in NETWORK:
        value = -1.8
    elif word in URLS:
        value = -1.2
    elif word in SERVICES:
        value = -0.8
    else:
        value = 0.0
    return None, value

programs.sol:
"""Predict consonant-cluster boundaries inside written words.

Short continuation fragments respond positively: two-letter consonant-vowel
fragments are strongest, while long fragments are weak. The response depends
on the initial consonant-letter class, is stronger after a fragment ending in
vowel-consonant, and increases for a repeated boundary letter. Camel-case and
all-capital continuations are attenuated. Vowel-initial tokens have a small
negative baseline; other boundaries are almost neutral. These are spelling
rules for Latin, Cyrillic and Greek letters, not a pronunciation analysis.
"""
import unicodedata
from functools import lru_cache

READS = ()
VOWELS = set('aeiouаеёиоуыэюяαεηιουω')
STOP_LETTERS = set('bcdgkpqtбгдкпт')
NASALS = set('mnмн')
LIQUIDS = set('lrлр')
FRICATIVE_LETTERS = set('fhjsvxzфвхжсшщз')

@lru_cache(None)
def base_letter(c):
    return unicodedata.normalize('NFD', c.lower())[:1]

@lru_cache(None)
def consonant(c):
    name = unicodedata.name(c, '') if c else ''
    alphabet = any(script in name for script in ('LATIN', 'CYRILLIC', 'GREEK'))
    return c.isalpha() and alphabet and base_letter(c) not in VOWELS

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    p = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            p = prefix.token_strings[-2]
    first, last = s[:1], p[-1:]
    if not (consonant(first) and consonant(last)):
        return None, -0.029 if base_letter(first) in VOWELS else 0.003

    n = len(s)
    ends_vowel = base_letter(s[-1:]) in VOWELS
    if n <= 2:
        value = 0.95 if n == 2 and ends_vowel else 0.70
    elif n == 3:
        value = 0.48
    else:
        value = 0.23 if n == 4 else 0.09

    c = base_letter(first)
    if c in NASALS:
        value *= 0.72
    elif c in LIQUIDS:
        value *= 0.55
    elif c in FRICATIVE_LETTERS:
        value *= 0.64
    elif c not in STOP_LETTERS:
        value *= 0.23

    if base_letter(p[-2:-1]) not in VOWELS:
        value *= 0.48
    if c == base_letter(last):
        value *= 1.36
    if first.isupper() and last.islower():
        value *= 0.31
    elif s.isupper():
        value *= 0.84
    return None, value

"""Opening round brackets: prose asides versus mathematical/code grouping.

The main response is negative for a space followed by '(', especially after
long lowercase words or sentence-ending punctuation. Function words in the
recent text indicate prose and strengthen this response. Capitals, repeated
parentheses and programming control words weaken or reverse it. A small
linear fit combines these properties. Non-parenthesis tokens are left at zero;
this deliberately does not explain their smaller, word-specific responses.
"""
READS = ()

FUNCTION_WORDS = frozenset('''
    a an the this that these those i me my we us our you your he him his
    she her they them their it its who which what where when why how
    and or but so if because although though while unless since whether
    as than of to in for on by at from with about into over under through
    between after before during without within is am are was were be been
    being do does did have has had can could may might must shall should
    will would not no only also such some all both each every any other
'''.split())


def prose_parenthesis(history):
    if not history:
        return 0.202
    previous = history[-1]
    word = previous.strip()
    last = previous[-1:] or ' '
    value = -0.059 - 0.141 * min(len(word), 12) / 12
    if word.istitle() and len(word) > 1:
        value += 0.018
    if word.isupper():
        value += 0.052
    if len(word) > 1 and word.isalpha() and word.islower():
        value -= 0.069
    if last in '.?!':
        value -= 0.195
    if last in '\"”’':
        value -= 0.146
    if last in '=+-*/^<>∈∑':
        value += 0.082
    if previous.isspace():
        value += 0.053
    if word in {'if', 'elif'}:
        value += 0.236
    if word in {'for', 'while', 'switch'}:
        value += 0.142
    if word in {'return', 'yield'}:
        value += 0.189
    if word in {'function', 'func', 'def'}:
        value += 0.069

    text = ''.join(history)
    value += (
        0.913 * sum(c in '()' for c in text)
        + 0.174 * sum(c.isupper() for c in text)
    ) / max(len(text), 1)
    for window, weight in ((16, -0.270), (64, -0.130)):
        recent = history[-window:]
        count = sum(t.strip().lower() in FUNCTION_WORDS for t in recent)
        value += weight * count / len(recent)
    return max(-0.63, min(0.22, value))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history = []
    else:
        _, history = carry
    token = prefix.token_strings[-1]
    if token == ' (':
        value = prose_parenthesis(history)
    elif token == '（':
        value = -0.227 if history else 0.096
    elif token == '.(':
        value = -0.138
    elif token == '(':
        value = 0.015 if history else 0.155
    elif token.strip() == '(-':
        value = 0.092
    elif token.strip() == '(!':
        value = 0.195
    else:
        value = 0.0
    history.append(token)
    if len(history) > 64:
        del history[0]
    return (document, history), float(value)

programs.luna:
"""Mark a capitalized word and its later subword pieces, as in proper names."""
READS = ()

def step(carry, prefix, upstream):
    previous_doc, in_capitalized_word = carry if carry is not None else (None, False)
    doc = prefix.document_ids[-1]
    if previous_doc is not None and doc != previous_doc:
        in_capitalized_word = False

    token = prefix.token_strings[-1]
    predicted = False
    for char in token:
        if char.isalpha():
            if not in_capitalized_word:
                in_capitalized_word = char.isupper()
            predicted |= in_capitalized_word
        elif char.isspace() or char.isdigit():
            in_capitalized_word = False
        elif char in "-'’ʼ":
            pass
        else:
            in_capitalized_word = False

    return (doc, in_capitalized_word), 0.04 if predicted else 0.0

programs.sol:
"""Respond to UTF-8 continuation fragments, especially split Han characters.

Raw continuation-byte tokens receive a positive pulse. A split Han character
gets a larger pulse, particularly just after a token beginning with a space.
For Han text, an unfinished character gets a stronger pulse than a finished
one. Smaller pulses mark other split scripts, space-prefixed Han/kana tokens,
chat's user-role header, NUL, and the single-byte C2 UTF-8 starter.
The few token IDs below identify space-plus-UTF-8-lead encodings, not words
or a learned activation lookup table.
"""
READS = ()

# Qwen's tokens for a space followed by one UTF-8 leading byte.
HAN_LEADS = {4891, 6567, 10236, 8908, 18137}  # E5, E6, E7, E8, E9
HANGUL_LEADS = {8620, 5140, 3315, 10764}  # EA, EB, EC, ED


def raw_byte(token_id):
    """Invert the tokenizer's standard ordering of the 256 single-byte tokens."""
    if 0 <= token_id <= 93:
        return token_id + 33
    if 94 <= token_id <= 105:
        return token_id + 67
    if 106 <= token_id <= 187:
        return token_id + 68
    if 188 <= token_id <= 220:
        return token_id - 188
    if 221 <= token_id <= 254:
        return token_id - 94
    if token_id == 255:
        return 173
    return -1


def unicode_band(code):
    if 0x3040 <= code < 0x3100:
        return 'kana'
    if 0x0400 <= code < 0x0530:
        return 'cyrillic'
    # These broad UTF-8 bands cover Han and Hangul, with adjacent blocks.
    if 0x4000 <= code < 0xA000:
        return 'han'
    if 0xA000 <= code < 0xE000:
        return 'hangul'
    if code < 0x800:
        return 'two_byte'
    if code < 0x4000:
        return 'symbols'
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        prev_token, prev_s, pending = -1, '', 'other'
    else:
        _, prev_token, prev_s, pending = carry
    b = raw_byte(token)
    previous_byte = raw_byte(prev_token)
    continuation = 128 <= b < 192 or s.startswith('\ufffd\ufffd')
    value = 0.0
    if continuation:
        last = prefix.text_prefixes[-1][-1:]
        unfinished = last == '\ufffd'
        band = pending if unfinished else unicode_band(ord(last))
        spaced = prev_s.startswith(' ')
        if band == 'han':
            if unfinished:
                value = 3.18 if spaced else 1.49
            elif spaced:
                value = 2.40 if s.startswith('\ufffd\ufffd') else 2.59
            else:
                value = 1.95 if 128 <= previous_byte < 192 else 1.05
        elif unfinished:
            value = 1.35 if band != 'other' else 1.17
        elif band == 'hangul':
            value = 1.10 if spaced else 0.61
        elif band == 'kana':
            value = 1.73 if spaced else 0.79
        elif band == 'cyrillic':
            value = 0.88 if spaced else 0.73
        elif band == 'two_byte':
            value = 0.73 if spaced else 0.42
        elif band == 'symbols':
            value = 0.68 if spaced else 0.44
        else:
            value = 0.60 if spaced else 0.46
    elif s.startswith(' ') and s.strip() and '\ufffd' not in s:
        first = ord(s.strip()[0])
        if 0x3400 <= first < 0xA000:
            value = 0.53
        elif 0x3040 <= first < 0x3100:
            value = 0.48
    elif s == 'user':
        value = 0.755 if prev_s == '<|im_start|>' else 0.06
    elif s == '\x00':
        value = 0.40
    elif b == 194:
        value = 0.30

    if token in HAN_LEADS or 228 <= b < 234:
        pending = 'han'
    elif token in HANGUL_LEADS or 234 <= b < 238:
        pending = 'hangul'
    elif token == 2858 or 224 <= b < 228:
        pending = 'symbols'
    elif not continuation:
        pending = 'other'
    return (doc, token, s, pending), float(value)

programs.haiku:
"""Activation of one MLP neuron-direction in layer 0 (down_proj component 518).

It is almost silent everywhere except on the word "of" (and " Of"/" OF"/"-of"),
where its sign depends on the noun just before "of":
  * after a noun naming a place, area or field of topic ("area of", "country of",
    "field of", "understanding of", "issue of") it is clearly positive;
  * after a noun naming an effect, measure or manner ("effect of", "impact of",
    "ratio of", "form of", "style of", "copies of") or a fixed phrase ("in spite of",
    "Battle of", "Art of") it is negative;
  * other "of" and all other tokens are about zero.
The program writes +0.6, -0.3 or 0.0 accordingly.
"""

PLACE_OR_TOPIC = {
    "area", "areas", "region", "regions", "country", "countries", "state", "states", "city",
    "cities", "town", "towns", "kingdom", "world", "center", "centre", "home", "south", "seat",
    "perimeter", "boundary", "base", "zone", "territory", "realm", "domain", "field", "fields",
    "topic", "issue", "question", "problem", "point", "points", "limit", "limits", "line",
    "parameter", "potential", "understanding", "knowledge", "interests", "principle", "tip",
}
EFFECT_OR_FORM = {
    "effect", "effects", "impact", "influence", "effectiveness", "efficiency", "results", "ratio",
    "cost", "costs", "density", "average", "presence", "expression", "importance", "dependence",
    "form", "forms", "style", "mode", "manner", "order", "copy", "copies", "pair", "pairs",
    "combination", "mix", "blend", "composition", "each", "cases", "spite", "behalf", "battle",
    "culture", "art", "portrait", "picture", "office", "courtesy", "memory", "spirit",
}
EXTENT = {"instance", "amount", "sum", "range", "side", "version", "period", "length", "value"}
PERCENT_USE = {"percent", "result", "use", "history", "view", "front", "sense", "volume", "one", "out", "all", "some", "most"}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word != "of" or len(prefix.token_strings) < 2:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if before in PLACE_OR_TOPIC:
        return carry, 0.6
    if before in EFFECT_OR_FORM:
        return carry, -0.3
    if before in EXTENT:
        return carry, 0.15
    if before in PERCENT_USE:
        return carry, -0.05
    return carry, 0.0

programs.luna:
"""A small group of 'of' phrases stands out; other relational nouns get a weaker guess."""

READS = ()

STRONG_HEADS = frozenset({"point", "country", "world", "field"})
OTHER_HEADS = frozenset({
    "area", "limit", "line", "region", "seat", "state", "question",
    "problem", "issue", "domain", "town", "city", "group", "part",
    "side", "kind", "sort", "number", "end", "use", "result", "range",
    "degree", "form", "piece", "way",
})


def preceding_word(prefix):
    """Recover the word before this token from a few pieces in the same document."""
    pieces = []
    for i in range(len(prefix.token_strings) - 2, max(-1, len(prefix.token_strings) - 7), -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        pieces.append(prefix.token_strings[i])
    word_text = "".join(reversed(pieces)).rstrip()
    if not word_text.split():
        return ""
    return word_text.split()[-1].strip(".,;:!?()[]{}\"'—–-").lower()


def step(carry, prefix, upstream):
    """Guess stronger after point/country/world/field, weaker after related heads."""
    if prefix.token_strings[-1] != " of":
        return None, 0.0
    head = preceding_word(prefix)
    if head in STRONG_HEADS:
        return None, 0.65
    if head in OTHER_HEADS:
        return None, 0.17
    return None, 0.0

programs.sol:
"""A surface detector for question marks, ampersands, and spaced periods.

Question marks are strong, but repeated marks, attached punctuation and line
breaks are weaker. Ampersands weaken in HTML escapes, logical AND and recent
TeX-like math. Successive spaced dots are not treated as isolated periods.
Other tokens predict zero; no word meanings or token-ID table are used.
"""
import re

READS = ()
QUESTIONS = '?？؟'
TEX_COMMAND = re.compile(r'\\[A-Za-z]{2,}')


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        recent, previous, dots = '', '', 0
    else:
        _, recent, previous, dots = carry
    bare = s.strip()
    value = 0.0
    if any(c in QUESTIONS for c in s):
        i = next(i for i, c in enumerate(s) if c in QUESTIONS)
        after = s[i + 1:]
        space = 0.20 if s.startswith(' ') else 0.0
        if sum(c in QUESTIONS for c in s) > 1:
            value = 0.70 + space
        elif '\n' in after:
            value = 0.30 if after.strip() else 0.57 + space
            if not after.strip():
                value -= 0.11 * (after.count('\n') > 1)
                value -= 0.10 * (s[i] == '？')
        elif after:
            value = 1.12 if after[0].isalpha() else 0.56
        else:
            value = 1.37
            if s[i] == '？':
                value = 1.05
            elif s[i] == '؟':
                value = 1.26
            value += space
            value -= 0.45 * ('<' in s[:i] or '>' in s[:i])
        if not recent:
            value *= 0.68
        elif bare in QUESTIONS and any(c in QUESTIONS for c in previous):
            value -= 0.60
    elif '&' in s or '＆' in s:
        if '&&' in s:
            value = 0.01 if '\n' in s else 0.14
        elif '&#' in s:
            value = 0.32
        elif '&quot' in s:
            value = 0.02
        elif '&lt' in s or '&gt' in s:
            value = 0.24
        elif bare in {'&', '＆'}:
            value = 1.07 if s.startswith(' ') else 0.99
            if TEX_COMMAND.search(recent) or '$' in recent:
                value = 0.53
            if not recent:
                value = 0.55
            if '\n' in s:
                value = 0.34 if s.startswith(' ') else 0.66
        else:
            if s.rstrip().endswith('&'):
                value = 0.84
            else:
                value = 0.70 if s.rstrip()[-1].isalpha() else 0.34
    elif bare == '.' and s.startswith(' '):
        if dots:
            value = 0.08 if dots == 1 else -0.10
        else:
            value = 0.26 if '\n' in s else 0.52
            if not recent:
                value = 0.11
    elif bare == '...' and s.startswith(' ') and '\n' not in s:
        value = 0.25
    dots = dots + 1 if bare == '.' else 0
    return (doc, (recent + s)[-240:], s, dots), float(value)

programs.luna:
"""Predict positive responses on question-mark and ampersand tokens."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if "?" in token:
        return None, 0.816
    if "&" in token:
        return None, 0.578
    return None, 0.0

programs.sol:
"""Detect rec-like spellings, especially recall and record, and memory words.

Bare rec is stronger than longer words; it is weaker inside appreciation or
deprecation, and stronger after a hyphen. Longer rec families differ in level;
receive/receptor and rectangle are weak despite their spelling. Precision and
appreciation, and a few memory/recommendation words in Chinese and Japanese,
are related responses. Many smaller lexical effects are left unmodeled. A
small echo persists on word fragments and on 'of', 'the', and 'for'.
State is cleared at document boundaries.
"""

READS = ()

# Similar-looking stems; these are spellings, not vocabulary token numbers.
STEMS = {'prec': 1.1, 'apprec': 1.5, 'proc': 1.1,
         'roc': 0.7, 'rem': 0.4, 'memo': 0.7, 'рек': 1.4}
MEMORY_WORDS = {'回忆', '回憶', '记得', '記得', '记录', '記録', '記錄'}
RECOMMEND_WORDS = {'推荐', '推薦', 'オススメ', 'おすすめ'}
PRECISION_WORDS = {'精准', '精準', '精确', '精確'}


def lexical(word, surface):
    if word in STEMS:
        return STEMS[word]
    if word in MEMORY_WORDS:
        return 1.4
    if word in RECOMMEND_WORDS:
        return 1.0
    if word in PRECISION_WORDS:
        return 0.8
    if word in {'记', '記', '忆', '憶'}:
        return 0.4
    if word.startswith('recall'):
        return 5.2 if word == 'recall' else 4.0
    if word.startswith(('recal', 'recap')):
        return 1.7
    if word.startswith('record'):
        if word.endswith(('ed', 'ing', 'ings')):
            return 1.2
        return 2.1 if surface == 'Records' else 1.7
    if word.startswith('recur'):
        if word.endswith(('ing', 'se', 'sed')):
            return 0.6
        if word.endswith('ly'):
            return 1.1
        return 2.4 if word.endswith(('ence', 'sion')) else 1.8
    if word.startswith('recent'):
        return 1.1 if word.endswith('ly') else 1.3
    if word.startswith('recip'):
        return 1.7 if word == 'recip' else (
            1.6 if word.startswith('reciproc') else 0.9)
    if word.startswith('recom'):
        if word == 'recom':
            return 1.5
        return 0.5 if word.endswith(('ed', 'ing', 's')) else 0.8
    if word.startswith(('recre', 'recru', 'recuper')):
        return 0.9
    if word.startswith(('recover', 'recycl')):
        return 0.65
    if word.startswith('recogn'):
        return 0.7 if word == 'recogn' else 0.35
    if word.startswith(('receiv', 'recept', 'reconsider', 'rech')):
        return 0.0
    if word.startswith('remember'):
        if not surface.startswith('remember') or word.endswith('ing'):
            return 0.95
        return 1.6
    if word.startswith(('remind', 'reminis', 'remarkab')):
        return 0.8
    if word.startswith('memor'):
        return 0.2 if word in {'memory', 'memor', 'memorial'} else 0.65
    if word.startswith(('precis', 'precip', 'recis', 'appreci')):
        return 0.55 if word.endswith('ly') else 0.95
    if word.startswith('rec'):
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, echo = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    surface = token.lstrip(" \t\n_./(-").rstrip()
    word = surface.lower()
    value = lexical(word, surface)
    if word == 'rec':
        value = 3.7
        if token == 'rec':
            value = 3.7 if previous and previous[-1].isalpha() else 4.1
            joined = (previous.strip() + token).lower()
            if joined.endswith(('deprec', 'apprec', 'aprec')):
                value = 2.6
        elif token == 'Rec':
            value = 4.7
        elif token == '-rec':
            value = 4.9
    if word == 'recent' and previous.strip().lower() in {'most', 'more'}:
        value = 0.85
    base = value
    if echo >= 0.9:
        if word == 'of':
            value += 0.35 * echo
        elif word in {'the', 'for'}:
            value += 0.12 * echo
        elif token and token[0].islower():
            value += 0.14 * echo
    return (doc, token, base), float(value)

