"""Use token spelling as a rough proxy for this sparse lexical response.

The largest examples cluster around record and recurrent, with smaller
responses on recent, recip-, recommend-, and other pieces containing rec.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if not word:
        return None, 0.0

    if word == "rec":
        value = 2.0
    elif word.startswith(("record", "recurrent")):
        value = 1.8
    elif word.startswith(("recent", "recip")):
        value = 1.3
    elif word.startswith(("recommend", "recreat")):
        value = 0.7
    elif word.startswith("retrospect"):
        value = 1.0
    elif "rec" in word:
        value = 0.55
    else:
        value = 0.0
    return None, value

"""Recognize a few relation words that tend to make this component fire.

It gives the largest estimate to the relative pronoun “who” and to “with”,
and a smaller estimate to common spatial and associative prepositions.
"""

READS = ()

SPATIAL_PREPOSITIONS = frozenset({
    "in", "on", "at", "within", "outside", "across", "around",
    "inside", "behind", "under", "over",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    if not word:
        return None, 0.0

    # These are word tokens, not fragments in the middle of a longer word.
    at_word_start = token[:1].isspace() or prefix.position == 0
    if not at_word_start:
        return None, 0.0

    if word == "who":
        return None, 0.54
    if word == "with":
        return None, 0.16
    if word == "of":
        return None, 0.03
    if word in SPATIAL_PREPOSITIONS:
        return None, 0.08
    return None, 0.0

"""A negative cue on substantial lowercase pieces of capitalized words."""

READS = ()


def step(carry, prefix, upstream):
    """Track a word's initial and mark its longer later pieces."""
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, capitalized = "", False
    else:
        _, word, capitalized = carry

    token = prefix.token_strings[-1]
    pulse = (
        len(token) >= 3 and token.isascii() and token.isalpha()
        and token.islower() and word and capitalized
        and len(word) + len(token) >= 6
    )

    for char in token:
        if char.isascii() and char.isalpha():
            if not word:
                capitalized = char.isupper()
            word += char
        else:
            word, capitalized = "", False

    return (doc, word, capitalized), (-0.019 if pulse else 0.0)

programs.sol:
"""Mostly a spelling detector for short 'ur' fragments.

Give the largest positive signal to tokens ending in ur, a smaller one
when letters complete that fragment, and little to ur late in a word.
Some common words and our/eur/aur spellings are weaker exceptions.
For standalone ur/urs, the preceding token's case and final vowel adjust
the strength. Cyrillic, Arabic and accented spellings are also included.
This approximates the dominant pattern, not every token-specific response.
"""
READS = ()

COMMON_OUR_WORDS = {
    'your': 0.0, 'our': 0.12, 'ours': 0.6, 'four': 0.12,
    'hour': 0.25, 'hours': 0.2, 'court': 0.1,
}
COMMON_UR_WORDS = {
    'during': 0.0, 'further': 0.0, 'furthermore': 0.0, 'für': 0.1,
    'sur': 1.7, 'nur': 1.7, 'zur': 1.1, 'dur': 2.1, 'leur': 0.55,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('._/()<>-').lower()
    boundary = raw[:1].isspace()
    if word in COMMON_OUR_WORDS and (
        boundary or raw[:1].isupper() or word in ('four', 'hour', 'hours', 'court')
    ):
        return None, COMMON_OUR_WORDS[word]
    if word in COMMON_UR_WORDS and (
        boundary or word in ('during', 'further', 'für')
    ):
        return None, COMMON_UR_WORDS[word]

    if word in ('ur', 'urs') and not boundary:
        previous = ''
        if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().strip('._/()<>-')
        capital = previous[:1].isupper()
        vowel = previous[-1:].lower()
        if word == 'ur':
            if capital:
                value = 5.4
            elif vowel and vowel in 'eéè':
                value = 3.4
            elif vowel and vowel in 'aiou':
                value = 4.0
            else:
                value = 4.8
        else:
            value = 2.5 if capital else 2.2
            if not vowel or vowel not in 'eéè':
                value = 3.5
        return None, value

    for pair, strength in (('ур', 2.8), ('юр', 2.0), ('ür', 2.2), ('ور', 1.2)):
        if pair in word:
            before, after = word.split(pair, 1)
            return None, strength / (1 + 0.25 * len(before) + len(after))
    if 'ur' not in word:
        return None, 0.0

    before, after = word.split('ur', 1)
    if before.endswith('o'):
        value = 1.1 if len(before) <= 2 and len(after) <= 1 else 0.12
        if word.startswith('your'):
            value = 0.0
    elif before.endswith('e'):
        value = 2.6 if not after and len(before) <= 2 else 0.4
        if word.startswith('europ'):
            value = 0.0
    elif before.endswith('a') and len(before) <= 2:
        value = 3.1 if not after else 2.0
    elif len(before) >= 3:
        value = 1.0 if not after else 0.12
    elif not after:
        value = 4.6 if not boundary else 3.6
        if before in ('b', 'p', 'k'):
            value += 0.7
    elif len(before) == 2:
        value = 0.6
    elif len(after) == 1:
        value = 2.5 if after in 'sirb' else 1.6
        if after in 'aeo':
            value = 1.0
        if word in ('pure', 'bury'):
            value = 2.5
        elif word in ('sure', 'turn'):
            value = 0.55 if word == 'sure' else 0.95
    else:
        value = 1.1 if not before else 0.8
        if word.startswith(('buri', 'burd', 'purif')):
            value = 1.8
        elif word.startswith('urr') and len(after) <= 3:
            value = 2.4
    return None, value

"""Local repetition of quotation and formatting marks.

A mark is stronger when similar marks occurred recently. We combine nearness
of the last mark (12-token decay) with a count of mark-containing tokens
decaying over 24 tokens, capped at four for prediction. Opening-like,
closing-like, and bracket-attached token shapes have different gains.
Ordinary words stay near zero; a quote fused to a word tends to be negative.
These gains are rounded training estimates, not a vocabulary lookup.
"""
import math

READS = ()
QUOTES = set('"\'“”„‘’«»‹›「」『』《》')
OPEN_QUOTES = set('“„‘«‹「『《')
CLOSE_QUOTES = QUOTES - OPEN_QUOTES - set('"\'')
MARKS = {
    'quote': QUOTES, 'tick': set('`'), 'dollar': set('$'),
    'pipe': set('|│┃'), 'dash': set('—–‐'), 'bullet': set('•・·'),
    'star': set('*'), 'underscore': set('_'), 'hyphen': set('-'),
}


def response(s, previous):
    """Return a mark family and (baseline, nearness gain, count gain)."""
    text = s.strip()
    if not text:
        return None, (0.22 if '\xa0' in s else -0.003, 0, 0)
    spaced = s[0].isspace()
    if any(c.isalnum() for c in text):
        if text[0] in OPEN_QUOTES or text[0] == '"':
            return 'quote', (-0.74, 0.8, 0.45)
        if text[0] in MARKS['dash']:
            return 'dash', (0.17, 1.36, 0.73)
        return None, (-0.003, 0, 0)
    if set(text) & QUOTES:
        if "''" in text:
            return 'tick', (0.30, 0.77, 0.43)
        if text[0] in OPEN_QUOTES:
            return 'quote', (0.02, 1.77, 0.61)
        if text[0] in CLOSE_QUOTES:
            return 'quote', (-0.20, 0.38, 0.72)
        mark = '"' if '"' in text else "'"
        if mark not in text:
            return 'quote', (-0.20, 0.38, 0.72)
        before, after = text.split(mark, 1)
        if mark in after and any(c not in QUOTES for c in text):
            return 'quote', (-0.03, 0.69, 0.39)
        if after.endswith('\\'):
            return 'quote', (-0.15, 0.61, 0.55)
        if before and before[-1] in '+.<':
            return 'quote', (-0.30, 0.44, 0.66)
        if '\n' in s or '\r' in s:
            return 'quote', (-0.09, 0.02, 0.19)
        if spaced and before in ('', '\\'):
            if not any(c in after for c in ',;:)]}'):
                return 'quote', (-0.18, 1.48, 0.50)
        if before and before[-1] in '([{=:':
            return 'quote', (0.02, 0.52, 0.33)
        if not before and not after:
            opening = not previous or previous[-1].isspace()
            opening = opening or previous[-1:] in '([{=,:;'
            return 'quote', ((-0.45, 1.09, 0.74) if opening
                             else (-0.41, 0.37, 0.60))
        return 'quote', (-0.36, 0.22, 0.32)
    if '`' in text:
        if text.startswith('```'):
            return 'tick', (-0.06, 0.66, 0.55)
        if text.startswith('``'):
            return 'tick', (0.26, 0.69, 0.77)
        return 'tick', ((0.17, 1.20, 0.67) if spaced else (0.10, 0.31, 0.69))
    if '$' in text:
        if '\n' in s:
            return 'dollar', (0.01, 0.13, 0.11)
        return 'dollar', ((0.15, 0.96, 0.61) if text.startswith('$$')
                          else (-0.06, 0.73, 0.46))
    if set(text) & MARKS['pipe']:
        if '\n' in s or text.count('|') > 1:
            return 'pipe', (0.29, 0.30, 0.09)
        return 'pipe', ((0.68, 0.62, -0.02) if spaced
                        else (0.45, 0.44, -0.07))
    if set(text) & MARKS['dash']:
        return 'dash', (0.17, 1.36, 0.73)
    if set(text) & MARKS['bullet']:
        return 'bullet', (0.32, 0.50, -0.06)
    if text.startswith('**'):
        return 'star', (0.34, 0.10, 0.46)
    if set(text) == {'*'}:
        return 'star', (-0.09, 0.17, 0.41)
    if text == '_' and spaced:
        return 'underscore', (0.01, 0.42, 0.49)
    if text.startswith('__'):
        return 'underscore', (-0.08, 0.57, -0.08)
    if set(text) == {'-'}:
        return 'hyphen', ((0.04, 0.21, 0.16) if len(text) > 1
                          else (-0.14, 0.34, 0.10))
    return None, (-0.09 if text == '\\' else -0.003, 0, 0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', {})
    doc, position, previous, memory = carry
    s = prefix.token_strings[-1]
    family, (base, near, repeated) = response(s, previous)
    last, count = memory.get(family, (-10000, 0))
    gap = position - last
    recent_count = min(count * math.exp(-gap / 24), 4) / 4
    value = base + near * math.exp(-gap / 12) + repeated * recent_count
    # Update each family once per token, including mixed punctuation tokens.
    chars = set(s)
    if any(c.isalnum() for c in s):
        chars -= set("'’")  # Apostrophes inside words are not quotation marks.
    for family, marks in MARKS.items():
        if chars & marks or (family == 'tick' and "''" in s):
            last, count = memory.get(family, (-10000, 0))
            count = 1 + count * math.exp(-(position - last) / 24)
            memory[family] = (position, count)
    return (doc, position + 1, s, memory), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:526 -- an "opening delimiter" detector.

The component fires on the symbols that open a quoted or marked-up span: an opening
quote mark (" ' ` “), a code-style quote after a colon or equals sign (":" ="), a dash
used as a separator, a pipe, a dollar sign for maths, bold stars, bullets. It fires
most when the symbol starts a new item in a list or structured text (after a comma,
colon, equals sign or bracket, or after "and"/"or"), and less when it follows
sentence-final punctuation or a prose function word. Ordinary words and most other
tokens give roughly zero.

The program: look up the newest token in a few named groups of symbols, give each
group a strength (roughly its typical activation in units of the component's own
scale), scale it up or down by what came just before, and return it.
"""

READS = ()

# Opening quotes and quote-like marks that begin a span, written with their leading space.
OPEN_QUOTES = {' "', " '", ' ``', ' `', ' "$', ' "/', ' "_', ' "\\', ' ‘'}
CURLY_OPEN = {' “', ' «', ' 「'}
TICKS = {'`', '``'}
DASHES = {' —'}
BARS = {' |', '|', '||'}
DOLLARS = {' $', '$', '$$', ' $$', ' $\\', '$\\'}
BOLD = {'**', ' **'}
DOTS = {'··', '•'}
# A quote that opens a value right after a key or equals sign, e.g. "key":"value".
KEY_VALUE = {':"', '":"', '="', '\\"\\'}
CODE_OPEN = {' {"', '("', "('", '["', " ['"}
# Symbols that respond only weakly.
WEAK = {"'", '”', '\xa0', ' –', '–', '--', '__', '*', ' \\"', '<<', ' <<', '「', '《'}
# Symbols that tend to push the activation slightly below zero.
NEG = {'\\', '",', "',", '."'}

# What came just before the symbol: a list or key/value context boosts it,
# a sentence end or prose function word damps it.
LIST_BEFORE = {',', ':', '=', '(', '[', '{', ' and', ' or', '",', "':", "',", '":'}
PROSE_BEFORE = {'.', '!', '?', 'the', ' the', ' a', ' to', ' that', ' as', ' of'}


def weight(tok):
    """Base strength of the newest token as a delimiter."""
    if tok in OPEN_QUOTES:
        return 1.0
    if tok in TICKS:
        return 1.1
    if tok in DASHES:
        return 1.0
    if tok in BARS:
        return 0.9
    if tok in DOLLARS:
        return 0.7
    if tok in BOLD:
        return 0.8
    if tok in DOTS:
        return 0.6
    if tok in KEY_VALUE:
        return 1.0
    if tok in CODE_OPEN:
        return 0.6
    if tok in CURLY_OPEN:
        return 0.55
    if tok in WEAK:
        return 0.3
    if tok in NEG:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    # Stateless: each position depends only on the newest token and the one before it.
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    w = weight(tok)
    if w and prev in LIST_BEFORE:
        w *= 1.4
    elif w and prev in PROSE_BEFORE:
        w *= 0.5
    return carry, float(w)

programs.luna:
"""Predict a response to opening quote and inline-format markers.

Layer 0's component is strongest at quotation and inline-code boundaries,
with smaller responses to dollar, bar, dash, and emphasis markers. This
punctuation-only rule misses context-dependent strengths and quieter signals.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    marked = token.lstrip()
    if not marked:
        return None, 0.0

    if marked.startswith("`"):
        return None, 1.0
    if marked.startswith("|"):
        return None, 0.8
    if marked.startswith("—"):
        return None, 0.9
    if marked.startswith(("$", "$$")):
        return None, 0.5
    if marked.startswith("**"):
        return None, 0.75
    if marked.startswith(("'", '"')):
        return None, 0.9 if token[0].isspace() else 0.1
    if marked.startswith(("“", "‘", "«", "「", "『")):
        return None, 0.4
    if marked.startswith(("–", "•")):
        return None, 0.35
    return None, 0.0

programs.sol:
"""A zero inside a decimal digit string, sensitive to its preceding digit.

The response is weakest in 20, moderate in 10, and strong after the other
digits. It grows beyond the second digit of a number. Decimal points and
commas leave only a small response. Fullwidth digits use the same rules.
"""
import unicodedata

READS = ()

# Zero as the second digit: 00, 10, 20, ... , 90.
ZERO_IN_PAIR = (0.95, 0.57, 0.00, 0.80, 0.94,
                1.06, 1.11, 1.14, 1.09, 1.18)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, before, run = ('', '', 0) if fresh else carry[1:]
    token = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    digit = len(token) == 1 and token in '0123456789'
    value = 0.0
    if token == '0':
        if fresh:
            value = 0.367
        elif run:
            value = ZERO_IN_PAIR[int(previous)]
            if run >= 2:
                value += 0.22 if previous in '12' else 0.14
                if run >= 5:
                    value -= 0.06
        elif previous in ('.', ',', ':'):
            if len(before) == 1 and before in '0123456789':
                strength = ZERO_IN_PAIR[int(before)]
                if previous == '.':
                    value = 0.20 * strength - 0.03
                    if before == '1':
                        value -= 0.04
                elif previous == ',':
                    value = 0.12 * strength - 0.03
                else:
                    value = 0.07 * strength - 0.004
            else:
                value = 0.02
        elif previous.isspace():
            value = -0.08
        else:
            value = -0.04
    return (doc, token, previous, run + 1 if digit else 0), value

