"""A narrow science-word proxy: predict a negative pulse on recognizable
physics, chemistry, and measurement terms, not on ordinary long words."""
READS = ()

SCIENCE_TERMS = frozenset({
    "atomic", "carrier", "charge", "density", "diameter", "electron",
    "equilibrium", "impedance", "lorentz", "mobility", "oxidation",
    "permittivity", "phosphorus", "plasma", "reduction", "singlet",
    "solvent", "species", "spin", "symmetry", "transition", "vortex",
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ""
    completed = []
    for char in prefix.token_strings[-1].lower():
        if char.isalpha():
            word += char
        else:
            if word:
                completed.append(word)
            word = ""
    match = word in SCIENCE_TERMS or any(
        item in SCIENCE_TERMS for item in completed
    )
    return (doc, word), -0.15 if match else 0.0

