RELATION = {
    "relate", "relates", "related", "relating", "relation", "relative", "relatively",
    "proportional", "close", "closer", "prior", "began", "begin", "begins", "starting",
    "start", "managed", "manages", "manage", "learn", "aim", "expect", "eager",
}
PREP_SCALE = {"to": 1.0, "from": 0.6, "by": 0.5, "through": 0.5, "into": 0.7}
TIER_VALUE = {"send": -2.2, "give": -1.3, "weak": -0.8, "relation": 0.2, "none": -0.1}


def step(carry, prefix, upstream):
    last = prefix.token_strings[-1]
    word = last.strip().lower()
    if word == "with":
        recent = {s.strip().lower() for s in prefix.token_strings[-5:-1]}
        return carry, (1.8 if recent & {"provide", "provides", "provided", "providing"} else 0.0)
    if any(c in last for c in ("给", "給", "赠送")):
        return carry, -2.0
    if word not in PREP_SCALE:
        return carry, 0.0
    recent = {s.strip().lower() for s in prefix.token_strings[-7:-1]}
    if recent & SENDING:
        tier = "send"
    elif recent & GIVING:
        tier = "give"
    elif recent & WEAK:
        tier = "weak"
    elif word == "to" and recent & RELATION:
        tier = "relation"
    else:
        tier = "none"
    value = TIER_VALUE[tier] * PREP_SCALE[word]
    if tier == "relation":
        value = TIER_VALUE[tier]
    return carry, float(value)

