"""A selective lexical approximation for the 'problem' word family.

Singular forms and fragments usually receive negative values, especially
'das Problem' and German/Nordic contexts. English 'the/this problem' is zero;
spaced English plurals are slightly positive. Unspaced lowercase singulars
receive a stronger negative value. At document start the family is positive.
All other tokens are zero. Most weak vocabulary-specific variation is left
unexplained rather than encoded in a lookup table.
"""
READS = ()

GERMAN = frozenset('das ein kein dieses ist nicht und der die zu mit ich'.split())
NORDIC = frozenset('och för på är inte som att og ikke til det med'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('/._(')
    lower = word.lower()
    previous = recent[-1] if recent else ''
    value = 0.0

    if lower == 'problem':
        value = -0.13 if word[0].isupper() else -0.05
        if token.startswith(('/', '_', '.')):
            value = -0.15
        elif not token[:1].isspace() and word[0].islower():
            value = -0.25

        if previous in ('the', 'this'):
            value = 0.0
        elif previous == 'das':
            value = -0.57
        elif previous == 'ein':
            value = -0.42
        elif previous in ('kein', 'dieses'):
            value = -0.33
        elif previous == 'bez':  # Polish 'without'
            value = -0.55
        elif sum(w in GERMAN for w in recent) >= 3:
            value = -0.40
        elif sum(w in NORDIC for w in recent) >= 3:
            value = -0.45
        elif not token[:1].isspace() and any(c in 'äöüß' for c in previous):
            value = -0.55
        elif previous in ('my', 'your'):
            value = -0.10
    elif lower in ('probl', 'proble'):
        value = -0.32
    elif lower == 'problems':
        value = 0.02 if token[:1].isspace() else -0.12
    elif lower in ('problema', 'problème'):
        value = -0.11
    elif lower == 'problemas':
        value = -0.01
    elif lower == 'problematic':
        value = -0.06
    elif lower == 'проблем':
        value = -0.17
    elif lower == 'проблемы':
        value = -0.06

    # At a document's first token, this word family has the opposite sign.
    if not recent:
        if lower in ('problem', 'problems', 'problema', 'problemas', 'problème',
                     'проблемы'):
            value = 0.12
        elif lower in ('probl', 'proble', 'problematic', 'проблем'):
            value = 0.05

    recent = (recent + (token.strip().lower(),))[-16:]
    return (doc, recent), value

