"""Least-squares weights on a few word-class features of the current token (no token table).
Problem-word pieces ('probl', 'Proble', 'problem' without a leading space) are strongly negative;
' problem' with a space, and XML-like tags, mildly negative; capitalised words, CJK and
non-ASCII tokens, and words after a determiner (the, a, das, ein...) mildly positive."""
import re

READS = ()
DETERMINERS = {"the", "a", "an", "this", "that", "these", "his", "her", "its", "their",
               "das", "ein", "eine", "dieses", "dein", "kein", "der", "die", "den", "dem"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    v = 0.0015
    if re.search(r"probl", s, re.I):
        v += -0.184 if not s.startswith(" ") else -0.037
    if re.fullmatch(r"</?\w+>", s):
        v += -0.035
    if re.fullmatch(r" ?[A-Z][a-z]+", s):
        v += 0.0066
    if any(ord(c) > 127 for c in s):
        v += 0.0027
    if "\n" in s:
        v += -0.005
    if re.fullmatch(r" ?[^\w\s]+", s):
        v += -0.003
    if re.match(r"[./]\w", s):
        v += -0.004
    if prev in DETERMINERS:
        v += 0.0038
    return None, float(v)

