import re

READS = ()


def ret_word(word):
    """Fixed strengths for familiar ret-stems and their written fragments."""
    if word in ('retired', 'retiring'):
        return -3.0
    if word == 'retir':
        return -1.7
    if word.startswith('retir'):
        return -2.5
    if word.startswith('retval'):
        return -2.3
    if word.startswith('retreat'):
        return -2.6
    if word.startswith('retent'):
        return -1.65
    if word.startswith('retain'):
        return -1.4
    if word.startswith('retailer'):
        return -1.1
    if word.startswith(('retail', 'retro')):
        return -1.5
    if word.startswith('retriev'):
        return -1.15
    if word.startswith(('retin', 'retract')):
        return -1.05
    if word.startswith('retard'):
        return -1.85 if word == 'retarded' else -1.1
    if word == 'rets':
        return -1.95
    if word == 'rett':
        return -1.3
    if word in ('retr', 'reten', 'reta'):
        return -0.85
    if len(word) == 4 and word.endswith('ret'):
        return -1.0
    if word == 'returned':
        return -0.55
    if word == 'returning':
        return -0.4
    if word == 'returns':
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_token = ''
    if carry is not None and carry[0] == doc:
        _, previous_token = carry
    # Ignore punctuation decorating a token, but retain word-boundary evidence.
    letters = re.search(r'[^\W\d_]+', token)
    word = letters.group().lower() if letters else ''
    continues = bool(letters and letters.start() == 0
                     and previous_token[-1:].isalpha())
    value = ret_word(word)
    if word == 'ret':
        value = -2.8 if continues else -3.6
        if letters.group() == 'Ret' and token.startswith(' '):
            value = -3.0
    elif continues and previous_token.strip().strip('._(-').lower() == 'ret':
        value = ret_word('ret' + word)
    # Single-character withdrawal/retirement is stronger than a compound.
    if '退' in token:
        if token.strip() == '退':
            value = -4.0 if previous_token.endswith('辞') else -7.5
        elif token.strip() == '退款':
            value = -1.2
        else:
            value = -2.8 if token.strip().startswith('退') else -1.3
    if token == '9':
        value = -0.145 if previous_token[-1:].isdigit() else 0.03
    return (doc, token), float(value)

