import re

READS = ()
# Stem: (default strength, exceptions for grammatical endings).
FAMILIES = {
    'conduct': (4.4, {'ed': 3.1, 'ing': 4.0, 'or': 3.0, 'ivity': 1.9}),
    'deduc': (2.15, {'t': 3.1}),
    'induc': (0.95, {'tion': 2.65, 'ed': 0.72}),
    'intro': (1.0, {'duction': 1.9, 'du': 1.6}),
    'reduc': (0.8, {'tion': 1.4, 'tions': 1.4, 'ed': 0.58}),
    'conclu': (1.7, {'sion': 1.95, 'sions': 1.6, 'ded': 1.45}),
    'construct': (0.85, {'': 1.1, 'or': 2.1, 'ors': 1.5, 'ive': 1.35}),
    'reconstruct': (0.43, {}),
    'destruct': (1.2, {}),
    'interrupt': (1.5, {'': 2.1}),
    'disrupt': (1.2, {'ive': 1.8}),
}
CHARACTERS = {'断': 3.8, '斷': 2.5, '导': 2.4, '導': 2.3,
              '引': 1.6, '結': 1.0, '结': 1.0,
              '中断': 2.8, '不断': 1.0, '结论': 1.5, '构造': 1.5}
ENDING = {'ing': 1.05, 'ive': 0.5, 'ively': 0.55, 'ors': 0.6,
          'ivity': 0.6, 'ed': 0.35, 's': 0.35, 'uce': 0.35,
          'ibility': 0.35}


def strength(word):
    # Conduct-related prefixes still respond when word pieces are joined.
    for prefix in ('super', 'non'):
        if word.startswith(prefix + 'conduct'):
            word = word[len(prefix):]
    if word.startswith('misconduct'): return 2.5
    for stem, (base, endings) in FAMILIES.items():
        if word.startswith(stem):
            return endings.get(word[len(stem):], base)
    return {'ded': 1.0, 'condu': 1.5, 'indu': 1.8, 'redu': 0.73}.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, old_value = '', 0.0
    if carry is not None and carry[0] == doc:
        _, prev, old_value = carry
    token = prefix.token_strings[-1]
    s = token.lower().strip(' \t\r\n_.$-/')
    joined = bool(token and token[0].isascii() and token[0].isalpha())
    word = prev + s if joined else s
    value = strength(s)
    if s == 'ind': value = 0.6 if token.strip() == 'Ind' else 0.1
    if s == 'ded' and joined: value = 0.4
    if s.startswith('duct'):
        value = 3.65 if s == 'duct' else 2.6
        if not joined: value = 1.65
        elif s == 'duct' and prev.endswith('con'):
            value = 3.7 if token.isupper() else 5.0
        elif 'pro' in prev: value *= 0.5
        if s == 'ductory': value = 0.7
    elif re.fullmatch(r'uct(?:ion|ions|ive|or)?', s):
        value = 2.65 if word.startswith('ind') else 1.7
    elif s.startswith('rodu'):
        value = 2.5 if word.startswith('int') else 0.9
    elif re.fullmatch(r'clu(?:de|ded|des|ding|s|sion|sions)?', s):
        value = 1.55 if word.startswith('con') else 0.2
    if joined and s in ENDING:
        value = strength(prev) * ENDING[s]
        if prev.endswith('duct') and s == 'ing':
            value = max(value, 0.85 * old_value)
    if token.lower() == ' of': value = 0.35 * old_value
    if s == 'introduction' and token.lstrip()[:1].isupper():
        value = 2.4
    if token in CHARACTERS: value = CHARACTERS[token]
    tail = re.search(r'[A-Za-z]+$', token)
    next_word = word[-40:] if tail else ''
    if tail and tail.start() > 0: next_word = tail.group().lower()
    return (doc, next_word, value), float(value)

"""Detect small powers and indices in mathematical and chemical notation.

Squares dominate, followed by cubes. Ordinary digits are weak; exponent marks,
roots, fractions, variable symbols and chemical-formula fragments strengthen
small digits. Letter-valued exponents instead give a small negative response.
Unicode superscripts/indices are recognized even across tokens.
Only 48 characters of preceding text are retained, resetting per document.
