    if '\ufffd' in token and previous:
        full = prefix.text_prefixes[-1]
        offset = (len(prefix.text_prefixes[document_start - 1])
                  if document_start else 0)
        text = full[offset:][-12:]
    else:
        text = (old + token)[-12:]
