"""Approximate a primarily negative response to written nine.

A nine following another digit is much stronger than an isolated nine.
The preceding digit sets its calibrated strength; decimal separators give
intermediate responses. Unicode normalization includes fullwidth digits.
English number words, several Chinese numerical forms, and September
also respond. Other digits have small calibrated responses depending on
whether they follow one, another digit, or non-numeric text.

Separate negative triggers cover tiger words, Chinese crab names, and
reasoning delimiters. Everything else receives -0.002: this approximation
does not model the many weaker, idiosyncratic lexical responses.
Only the previous token is retained, with a reset between documents.
"""
import unicodedata

READS = ()

# Nine's response after each preceding digit, ordered 0 through 9.
NINE_ENDINGS = (-0.43, -0.45, -0.63, -0.56, -0.56,
                -0.59, -0.65, -0.56, -0.55, -0.43)
# Small responses for digits other than nine, indexed 0..8.
# Distinguish standalone digits, endings after one, and other number endings.
DIGIT_ALONE = (0.005, 0.000, -0.003, 0.005, -0.004,
               -0.015, -0.014, 0.041, 0.071)
DIGIT_AFTER_ONE = (0.008, -0.025, -0.012, -0.042, 0.029,
                   0.030, 0.038, 0.064, 0.072)
DIGIT_IN_NUMBER = (-0.002, 0.006, 0.023, 0.010, 0.040,
                   0.013, -0.022, -0.012, -0.050)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    normalized = unicodedata.normalize('NFKC', token)
    last = unicodedata.normalize('NFKC', previous[-1:])
    digit_before = len(last) == 1 and last in '0123456789'
    word = token.strip().lower()
    value = -0.002
    if normalized == '9':
        if digit_before:
            value = NINE_ENDINGS[int(last)]
        elif previous.endswith('\\x'):
            value = -0.02  # Hexadecimal byte escape.
        elif last == '.':
            value = -0.35
        elif last == ',':
            value = -0.26
        elif last.isalpha():
            value = -0.24
        elif '\n' in previous:
            value = -0.16
        else:
            value = -0.13
    elif len(normalized) == 1 and normalized in '012345678':
        responses = (DIGIT_AFTER_ONE if last == '1' and digit_before
                     else DIGIT_IN_NUMBER if digit_before else DIGIT_ALONE)
        value = responses[int(normalized)]
    elif word in {'nine', 'ninth'}:
        value = -0.12
    elif word in {'seven', 'eight'}:
        value = 0.07
    elif word == 'nineteen':
        value = -0.21
    elif word == 'ninety':
        value = -0.27
    elif word == '-nine':
        value = -0.46 if previous.strip().lower() == 'ninety' else -0.67
    elif word == 'september':
        value = -0.10 if token.startswith(' ') else -0.04
    elif token == '九':
        value = -0.18
    elif token == '十九':
        in_long_number = bool(previous) and previous[-1] in '二三四五六七八'
        value = -0.75 if in_long_number else -0.51
    elif token in {'第九', '九年'}:
        value = -0.38
    elif word in {'tiger', 'tigers'}:
        value = -0.25
    elif token in {'虎', '老虎'}:
        value = -1.05 if token == '虎' else -0.65
    elif token in {'蟹', '螃蟹'}:
        value = -0.42 if token == '蟹' else -0.33
    elif token == '<think>':
        value = -0.066
    elif token == '</think>':
        value = -0.178
    return (doc, token), float(value)

