import re

READS = ()

PHRASES = (
    (2.0, ('Fiscal Year',)),
    (1.5, ('Nuclear Power',)),
    (1.3, ('fiscal year',)),
    (1.0, ('fiscal years', 'Mexico City', 'Nuclear Power Plant')),
    (0.9, ('nuclear reactor', 'nuclear reactors')),
    (0.75, ('nuclear power', 'Space Station', 'Power Station', 'Solar System')),
    (0.6, ('New York City', 'Northern Ireland', 'Sierra Leone',
           'Solar Energy', 'atomic number', 'Orange County')),
    (0.5, ('Federal Government', 'Electrical Engineering', 'nuclear program',
           'Pythagorean theorem', 'pythagorean theorem', 'Solar energy')),
    (0.4, ('solar system', 'solar power', 'Oklahoma City', 'Homeland Security')),
    (0.35, ('South Korea', 'Rhode Island', 'São Paulo', 'Federal Reserve')),
    (0.25, ('solar energy', 'space station', 'calendar year', 'magnetic fields')),
    (0.2, ('San Francisco', 'magnetic field')),
    (-0.18, ('no more', 'no longer', 'not necessarily')),
)
ENDINGS = {}
for value, phrases in PHRASES:
    for phrase in phrases:
        ENDINGS.setdefault(phrase.rsplit(' ', 1)[-1], []).append((phrase, value))

CONTRACTION_STEMS = frozenset((
    'don', 'doesn', 'didn', 'isn', 'aren', 'wasn', 'weren',
    'hasn', 'haven', 'hadn', 'wouldn', 'couldn', 'shouldn',
))
MARKERS = {'<tool_response>': 0.13, '<tool_call>': -0.11,
           '</tool_call>': 0.07, '<think>': 0.08}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, count = '', '', 0
    else:
        _, recent, previous, count = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    text = (recent + token)[-80:]
    value = MARKERS.get(token, 0.0)

    if count == 0 and token == 'Title':
        value = -0.33
    elif count == 1 and previous == 'Title' and token == ':':
        value = 0.436
    elif word == 'States' and previous.strip() == 'United':
        value = 0.15 if recent.endswith('the United') else 0.25
        if previous == 'United':
            value = 0.60
        if recent.endswith('(United'):
            value = 0.75
        if count == 1:
            value = 1.0
    elif token == ')\n' and recent.endswith('United States'):
        value = 0.75
    elif token == '.gov':
        # Domain names, rather than the .gov suffix alone, set the strength.
        label = re.search(r'[\w-]+$', recent.lower())
        label = label.group() if label else ''
        value = 0.50
        if label in {'nih', 'cdc', 'fda', 'cancer'}:
            value = 1.0
        elif label in {'treasury', 'sec', 'congress', 'nasa', 'ca'}:
            value = 0.20
        elif label in {'uk', 'ci'}:
            value = 0.08  # package/file prefixes, not government web addresses
    elif token == '.;':
        initial = previous.strip().lstrip('.')
        if len(initial) == 1 and initial.isascii() and initial.isupper():
            value = 0.55  # bibliographic initials
    elif token == ':' and previous.strip() == 'PMID':
        value = 0.73
    elif token == '_INCREMENT' and previous.strip() == 'AUTO':
        value = 0.54
    elif word.lower() in CONTRACTION_STEMS and token.startswith(' '):
        value = 0.065
    elif re.fullmatch(r'\.?assert(?:[A-Z_]\w*)?', word):
        value = -0.13 if word == 'assert' else -0.20

    for phrase, response in ENDINGS.get(word, ()):
        if text.endswith(phrase):
            value = response
            break
    return (doc, text, token, count + 1), value

