programs.sol:
"""Predict a pulse for document-opening numeral tokens.

Repeating the same opening token preserves the pulse. A change ends it, with
only a rapidly fading tail on subsequent digit tokens. Fullwidth digits have
roughly one-third the ASCII response. Initial escaped line breaks and spaced
comment asterisks receive smaller pulses; everything else predicts zero.
"""
from param_decomp.explain.atoms import FULLWIDTH_DIGITS

READS = ()
DIGIT_STRENGTH = {
    '0': 3.241, '1': 4.390, '2': 5.495, '3': 3.872, '4': 4.602,
    '5': 5.133, '6': 5.031, '7': 4.776, '8': 4.254, '9': 5.188,
}


def digit_response(token):
    if token in FULLWIDTH_DIGITS:
        return 0.36 * DIGIT_STRENGTH[chr(ord(token) - 0xFEE0)]
    return DIGIT_STRENGTH.get(token, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        opening, distance = token, 0
    else:
        _, opening, distance = carry
        if distance or token != opening:
            distance += 1

    value = 0.0
    strength = digit_response(token)
    if distance == 0:
        value = strength
        if token == r'\n':
            value = 0.83
        elif token == ' *':
            value = 0.87
    elif strength and distance <= 8:
        height = 0.52 if digit_response(opening) else 0.07
        width_scale = 0.36 if token in FULLWIDTH_DIGITS else 1.0
        value = width_scale * height / distance ** 1.8

    return (doc, opening, distance), value

