    if lower in {'commercial', 'commercially', 'traffic'}:
        return 0.55
    if word in CHINESE_FORMS:
        return CHINESE_FORMS[word]
    if '客户' in word or '客戶' in word:
        return 4.4 if word.endswith('的') else 3.5
    if word in {'お客', 'お客様', 'khách', '고객'}:
        return 2.0
    if lower in {'пациент', 'паци'}:
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

"""A detector for pauses, omissions, and endings, primarily written as dots.

Recognize ellipses and dotted leaders, including Unicode and LaTeX forms.
Their strength depends on the number of dots and the surrounding formatting;
an ordinary full stop is quiet. Chat-turn and thinking-span endings are
positive too. Short turns and tool-message endings have smaller responses.
Repeated question/exclamation marks and low double quotes get smaller positive
responses; a tool-response closing tag gets a small negative response. Other
tokens normally return zero, leaving weaker lexical effects unexplained.
"""
import math
import re

READS = ()
DOTS = re.compile(r'[.…]{2,}|…|·{2,}|・{2,}|。{2,}|․')
LATEX_DOTS = re.compile(r'\\(ldots|cdots|vdots|ddots|dots)$')
REPEATED_MARKS = re.compile(r'([!?！？，,])\1+')
# Calibration by the length of a short ASCII dot run, not by token identity.
SHORT_DOTS = (0.0, 0.0, 0.93, 1.10, 2.25, 3.10, 4.08, 3.63, 4.87, 4.05)


def punctuation(token, previous):
    if token == ' .':
        return 0.43 if previous == ' .' else 0.25 if previous == '.' else 0.0
    if token.strip(' ') == '„':
        return 0.35 if token.startswith(' ') else 0.60
    match = DOTS.search(token)
    if match:
        dots = match.group()
        n = len(dots)
        if dots == '․':
            value = 0.71
        elif dots[0] in '·・。':
            value = 0.44 * n
            if dots[0] == '·':
                value = 0.60 * n
            elif dots[0] == '。':
                value = 0.36 * n
        elif '…' in dots:
            ellipses = dots.count('…')
            value = min(3.3, 1.3 * ellipses - 0.44)
            if dots.startswith('…'):
                value += 0.75 * dots.count('.')
        elif n >= 48:
            value = 2.65
        elif n >= 10:
            value = 5.6
        else:
            value = SHORT_DOTS[n]
        if token.startswith(' ') and dots[0] == '.' and n != 3:
            value += 0.45
        suffix = token[match.end():]
        if '\n' in token or '\r' in token:
            if dots in ('...', '…'):
                value = 0.08 if not suffix.strip() else 0.30
            elif dots == '..':
                value = 0.68 if token.startswith(' ') else 0.42
            else:
                value *= 0.32
        elif '/' in token:
            value = 0.33 * token.count('..')
        elif suffix and not suffix[0].isalpha():
            value *= 0.72
            if token.lstrip().startswith('[') and suffix == ']':
                value *= 1.6
        return value
    match = REPEATED_MARKS.search(token)
    if match:
        mark, n = match[1], len(match[0])
        value = min(1.3, 0.16 * n)
        if mark == '?':
            value = 0.13 * n + (0.15 if token.startswith(' ') else 0.0)
        elif mark == ',' and token.startswith(' '):
            value += 0.43
        elif mark == '！':
            value = 0.13 * n
        if '\n' in token:
            value *= 0.4
        return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', ''
    else:
        position, previous, tail = carry[1] + 1, carry[2], carry[3]
    token = prefix.token_strings[-1]
    tail = (tail + token)[-16:]
    if token == '<|im_end|>':
        level, short_turn = 2.615, 1.107
        if previous == '</tool_call>':
            level, short_turn = 2.223, 1.237
        elif previous == '</tool_response>':
            level, short_turn = 2.281, 1.154
        value = level - short_turn / math.sqrt(position + 1)
    elif token == '</think>':
        value = 1.04
    elif token == '<think>':
        value = 0.38
    elif token == '</tool_response>':
        value = -0.18
    elif token == '<|endoftext|>':
        value = 0.03
    else:
        command = LATEX_DOTS.search(tail)
        if command:
            value = {'ldots': 0.86, 'cdots': 0.68, 'vdots': 0.27,
                     'ddots': 0.43, 'dots': 0.90}[command[1]]
        else:
            value = punctuation(token, previous)
    return (doc, position, token, tail), float(value)

