"""Recognize message-end markers and punctuation used as an ellipsis or pause."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous_doc, previous_dots = carry or (None, 0)
    if document != previous_doc:
        previous_dots = 0

    dots = token.count(".")
    ellipses = token.count("…")
    if token == "<|im_end|>":
        value = 2.27
    elif dots >= 4:
        value = 2.9
    elif ellipses >= 2:
        value = 2.2
    elif dots >= 3 or ellipses == 1:
