programs.haiku:
"""Layer 0, MLP down-projection, component 559.

What it does: it reads Arabic-script text. On a token written in Arabic letters it
pushes the activation negative when the token contains long-vowel or glide letters
(ي strongly; و, ى, ا less so), and positive when it contains pharyngeal or emphatic
consonants (ذ ه ق ط ظ ع ض خ ح). Tokens with no Arabic letters get 0.

The sign is the main thing: the strongest activations (about -2 to -3) are on
Arabic fragments of longer words, such as the ي / ز / ين pieces of transliterated
foreign words, while the positive ones are about +0.5 to +1.

Chat markers such as </tool_call> and <think> get fixed values.

Predictions are made from the current token only, which is what the layer-0 MLP sees
(plus a little attention context, which this ignores).
"""

import unicodedata

READS = ()

# Letter weights: long vowels and glides are negative, pharyngeal/emphatic
# consonants are positive, and a few foreign-sound letters are mildly negative.
LETTER_WEIGHT = {"ي": -0.7, "و": -0.4, "ى": -0.4, "ا": -0.1}
for _c in "ذهقطظعضخح":
    LETTER_WEIGHT[_c] = 0.36
for _c in "إغجزت":
    LETTER_WEIGHT[_c] = -0.17
BIAS = -0.03  # small shift for every Arabic-script token

# A few chat-template markers that the component also responds to.
MARKER_VALUE = {"</tool_call>": -0.3, "</tool_response>": 0.24, "<think>": 0.22, "</think>": -0.13}


def is_arabic(ch):
    return unicodedata.name(ch, "").startswith("ARABIC")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MARKER_VALUE:
        return carry, MARKER_VALUE[token]
    if not any(is_arabic(ch) for ch in token):
        return carry, 0.0
    value = BIAS
    for ch in set(token):
        value += LETTER_WEIGHT.get(ch, 0.0)
    return carry, float(value)

