"""A small empirical cue for Arabic-script token pieces, not a word parser."""
import unicodedata

READS = ()

# Rough activation tendencies seen for these Arabic letters in the harvest.
NEGATIVE_TENDENCY = frozenset("يواغرسزفك")
POSITIVE_TENDENCY = frozenset("همقدطک")


def step(carry, prefix, upstream):
    for ch in prefix.token_strings[-1]:
        if "ARABIC" not in unicodedata.name(ch, "") or not ch.isalpha():
            continue
        if ch in NEGATIVE_TENDENCY:
            return None, -0.35
        if ch in POSITIVE_TENDENCY:
            return None, 0.25
        return None, -0.05
    return None, 0.0

programs.sol:
"""Approximate the component's strong negative responses at inflection boundaries.

Common plural, gender and case endings must be separate tokens directly after
an alphabetic stem. Longer preceding pieces and recognizable noun/adjective
morphology strengthen the response; vowel-final Latin stems weaken it.
Other tokens get a small baseline, with a small positive response to several
verb, adjective and agent-forming endings. No whole-word lookup is used.
"""
import re

READS = ()
PLURALS = frozenset(('es', 'as', 'os', 'en'))
GENDER = frozenset(('a', 'e', 'i', 'o'))
OBLIQUE_PLURALS = frozenset(('ов', 'ам', 'ами', 'ах', 'ям', 'ями', 'ях'))
RUSSIAN_CASE = frozenset(('ом', 'ой', 'ей', 'ми'))
RUSSIAN_VOWELS = frozenset(('а', 'е', 'ы', 'у', 'ю'))
VOWELS = frozenset('aeiouyаеёиоуыэюя')
# Productive noun and adjective stem endings (not a list of whole words).
NOMINAL = ('tion', 'sion', 'ment', 'ent', 'ist', 'ism',
           'тор', 'ист', 'мент', 'тель',
           'ник', 'граф', 'грам', 'лог', 'ект')
CLASSICAL_ROOTS = ('text', 'текст', 'form', 'gram', 'graph', 'log')
ADJECTIVAL = ('al', 'ic', 'ous', 'ive', 'able', 'ible', 'lich', 'isch')

ENDINGS = (PLURALS | GENDER | OBLIQUE_PLURALS | RUSSIAN_CASE |
           RUSSIAN_VOWELS | frozenset(('s', 'us', 'em', 'is', 'um', 'ibus',
                                      'orum', 'ur', 'eur', 'ateur', 'ian', 'ians')))


def has_formative(stem, endings):
    return any(stem.endswith(x) and len(stem) >= len(x) + 2 for x in endings)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    piece, word = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    ending = token.lower()
    n = min(len(piece), 12)
    # Letters beyond 2, 4 and 6 give a piecewise length response.
    a, b, c = (max(0, n - k) for k in (2, 4, 6))
    vowel = piece[-1:].lower() in VOWELS
    value = 0.003
    attached = bool(piece) and token.isalpha()
    if attached:
        if ending == 's':
            value = 0.04 - 0.04*a - 0.08*b + 0.06*c
            if vowel:
                value += -0.035 + 0.035*a
        elif ending in PLURALS:
            value = -0.01 - 0.105*a - 0.015*b
            if vowel:
                value += 0.07 + 0.08*a
        elif ending in GENDER:
            value = 0.02 - 0.06*a - 0.09*b + 0.07*c
            if vowel:
                value += 0.01 + 0.05*a
        elif ending in OBLIQUE_PLURALS:
            value = -0.2 - 0.22*a + 0.10*b
            if ending == 'ами':
                value -= 0.25
        elif ending in RUSSIAN_CASE:
            value = -0.07 - 0.12*a + 0.035*c
            if ending == 'ми' and vowel:
                value -= 0.25
        elif ending in RUSSIAN_VOWELS:
            value = 0.025 - 0.095*a + 0.03*c
        elif ending in ('us', 'em', 'is', 'um', 'ibus', 'orum'):
            value = -0.01 - 0.06*a - 0.035*b
            if vowel:
                value += 0.06*a
            if ending == 'ibus':
                value -= 0.3
        elif ending in ('ur', 'eur', 'ateur'):
            value = 0.03 - 0.05*a
        elif ending in ('ian', 'ians'):
            value = 0.015 - 0.10*c
        elif ending in ('ing', 'ed', 'er', 'y', 'ado'):
            value = 0.06
        # Nominal/adjectival morphology makes the stem boundary less ambiguous.
        stem = word.lower()
        if ending in ENDINGS:
            if any(stem.endswith(x) for x in CLASSICAL_ROOTS):
                value -= 0.25
            elif has_formative(stem, NOMINAL):
                value -= 0.30
            elif has_formative(stem, ADJECTIVAL):
                value -= 0.08
        # Extra word characters before the last token slightly strengthen endings.
        if value < 0:
            value -= 0.01 * min(max(len(word) - len(piece), 0), 8)
    match = re.search(r'[^\W\d_]+$', token)
    tail = match.group() if match else ''
    word = (word + tail)[-64:] if tail == token else tail[-64:]
    return (doc, tail, word), float(max(-1.5, value))

"""Approximate a lexical answer-introduction feature, not answer correctness.

Negative cues are `answer` (especially after `correct`), `Answer:`,
`answer is`, and LaTeX `boxed`. Plural `answers` usually reverses the sign.
A short text tail recognizes split answer labels and nearby continuations;
state is reset between documents. Other tokens receive a near-zero prediction.
"""
import re

READS = ()
QUALIFIERS = {
    "correct": -0.90,
    "assistant": -0.69,
    "final": -0.40,
}
ANSWER = re.compile(r"\b(answer|ans|ответ)\s*$", re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    recent, previous = ("", "") if start else carry[1:]
    raw = token.strip()
    word = raw.lower()
    prev = previous.strip().lower()
    answer_before = ANSWER.search(recent)
    value = 0.002

    if raw in ("answer", "Answer"):
        value = -0.28 if token.startswith(" ") else 0.0
        if prev in QUALIFIERS and token.startswith(" "):
            value = QUALIFIERS[prev]
        elif prev == "to":
            value = -0.05
    elif raw == "Ans":
        value = -0.50 if token.startswith(" ") else -0.72
    elif raw in ("ANS", "ANSW"):
        value = -0.55 if raw == "ANSW" else -0.15
    elif word == "answers":
        value = -0.40 if prev == "correct" else 0.19
    elif word == "boxed":
        value = (-0.18 if token.startswith(" ") else
                 (-1.65 if previous.endswith("\\") else -1.05))
    elif token == " is":
        value = (-0.424 if start else
                 (-0.62 if answer_before else -0.015))
        if re.search(r"\bcorrect answer$", recent, re.I):
            value = -0.76
    elif raw == ":":
        if answer_before:
            label = answer_before.group(1)
            value = -1.25 if label in ("Answer", "Ans") else -0.60
            if label == "ANS":
                value = -0.30
            elif token.startswith(" "):
                value = -0.70
            elif previous == " Answer" and "\n" in token:
                value = -0.83
        elif start and token == ":":
            value = -0.353
        elif prev in ("solution", "output", "explanation"):
            value = -0.28
    elif word in ("choice", "option"):
        if prev == "correct" and token.startswith(" "):
            value = -0.58
        elif word == "choice" and answer_before:
            value = -0.70
    elif token == "{" and prev == "boxed":
        value = -0.42
    elif word in ("to", "for", "would", "should") and answer_before:
        value = -0.30 if word in ("to", "for") else -0.16
    elif (word == "be" and
          re.search(r"\banswer (?:would|should|will)$", recent, re.I)):
        value = -0.24

    return (doc, (recent + token)[-80:], token), float(value)

