"""Detect 'et al.' citations and morning spellings, especially 朝.

The positive citation pulse is on 'al', followed by a three-token fading
echo. English morning words and East Asian morning characters have the
opposite sign. 朝 still responds when used for a dynasty or 'toward'.
Other tokens receive only a small baseline; this misses many weak effects.
"""
READS = ()

MORNING_SPELLINGS = {
    '朝': -5.23, '明朝': -2.76, '清朝': -2.22, '王朝': -1.80,
    '朝着': -2.47, '朝阳': -1.40, '朝廷': -1.34, '朝鲜': -0.91,
    '晨': -1.29, '早晨': -1.66, '清晨': -1.49, '早上': -1.26,
    '上午': -0.61, '黎明': -0.69, '晓': -0.46, '曉': -0.60,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, age = '', 4
    if carry is not None and carry[0] == doc:
        previous, age = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = MORNING_SPELLINGS.get(word, -0.002)
    if word.lower() in {'morning', 'mornings'}:
        value = -0.95 if word.islower() else -0.91
        previous_word = previous.strip().lower()
        if previous_word == 'this':
            value = -1.18
        elif previous_word == 'good':
            value = -0.76
        elif previous_word in {'the', 'every'}:
            value = -1.04
    if age < 3:
        value += (0.15, 0.042, 0.017)[age]
    citation = token == ' al' and previous.strip().lower() == 'et'
    if citation:
        value = 0.88 if previous.startswith(' ') else 0.38
    return (doc, token, 0 if citation else min(age + 1, 4)), float(value)

