"""Score listed fault, harm, cost, and physical-factor words negatively.

Join subword pieces into the current word; unlisted words score zero.
"""

import re

READS: tuple[str, ...] = ()

FAULTS = {
    "error", "mistake", "failure", "bias", "variance", "uncertainty",
    "deviation", "distortion", "noise", "entropy", "confusion",
    "contradiction", "dispute", "tension", "stress", "strain", "friction",
    "variability",
}
HARMS = {
    "risk", "danger", "hazard", "waste", "damage", "pain", "anxiety",
    "cancer", "disease", "mortality", "violence", "bullying", "stigma",
    "contamination", "pollution", "impurity", "toxic", "corrosion",
    "liability", "cholesterol",
}
COSTS = {
    "cost", "expense", "debt", "tax", "fee", "loss", "interest",
    "income", "revenue", "capital", "profit",
}
ADVERSE_FACTORS = {
    "heat", "fat", "sugar", "glucose", "oxygen", "nitrogen", "carbon",
    "ammonia", "moisture", "torque", "pressure", "energy", "waste",
}
STRIP = " \t\r\n.,;:!?()[]{}<>\"'`*_-/\\“”‘’"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    piece = prefix.token_strings[-1]
    part = piece.strip()
    if piece and not piece[0].isspace() and part[:1].isalnum():
        if previous and previous[-1:].isalnum():
            word = previous + part
        else:
            word = part
    else:
        word = part

    variants = set()
    for piece in re.findall(r"[A-Z]+(?=[A-Z][a-z]|\b)|[A-Z]?[a-z]+", word):
        clean = piece.lower().strip(STRIP)
        variants.add(clean)
        if clean.endswith("s"):
            variants.add(clean[:-1])
        if clean.endswith("ies"):
            variants.add(clean[:-3] + "y")

    if variants & FAULTS:
        value = -0.8
    elif variants & HARMS:
        value = -0.7
    elif variants & COSTS:
        value = -0.65
    elif variants & ADVERSE_FACTORS:
        value = -0.55
    else:
        value = 0.0
    return (doc, word), value

programs.haiku:
"""Availability detector: layer 0, MLP down_proj, component 566.

What it responds to, in plain terms:
- The word "available" itself (strongest, about 1.8).
- Close kin of "available" and words for serving or supplying: accessible, availability,
  serve/serves/served, supply/supplied, and Chinese 供 ("supply / for use"). Moderate.
- The preposition right after an availability word: "is available FOR", "ready FOR",
  "open TO" (about 1.5 for "for", 1.0 for "to").
- Ordinary "for" (about 0.8), except after "look", "responsible", "account", where it is ~0
  ("responsible for", "look for", "account for" are not about availability).
Everything else is about 0. The component's signal is mostly this lexical "available for"
meaning, so the rules below capture most of its variance.
"""

READS = ()

AVAILABLE = {"available"}
ACCESS = {"accessible", "accessibility", "availability", "disponible", "доступ"}
FOR_WORDS = {"для", "für", "för", "để"}
SERVE = {"serve", "serves", "served", "serving", "supply", "supplies", "supplied"}
OFFERED = {"available", "accessible", "ready", "open", "offered", "provided"}
SEEK = {"look", "looking", "responsible", "account", "accounting"}


def word(s):
    return "".join(c for c in s.lower() if c.isalpha())


