    raw = prefix.token_strings[-1]
    cur = word(raw)
    prev = word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if cur in AVAILABLE:
        value = 1.8
    elif cur in ACCESS:
        value = 1.0
    elif cur in SERVE:
        value = 0.8
    elif cur in FOR_WORDS:
        value = 0.5
    elif cur == "ready":
        value = 0.5
    elif raw.strip() == "供":
        value = 2.0
    elif cur == "for":
        if prev in OFFERED:
            value = 1.5
        elif prev in SEEK:
            value = 0.0
        else:
            value = 0.8
    elif cur == "to" and prev in OFFERED:
        value = 1.0
    else:
        value = 0.0
    return None, value

