"""Approximate a response to 'for' and closely related availability or supply terms."""
READS = ()

AVAILABILITY_WORDS = {"available", "accessible"}
SUPPLY_WORDS = {"served", "supply"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token == "for" or token.endswith(("_for", "-for")):
        return None, 0.82
    if token in AVAILABILITY_WORDS:
        return None, 1.0
    same_document = (
        len(prefix.token_strings) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
