programs.sol:
"""Approximate an involvement/contribution signal using readable word classes.

Participation followed by 'in' and contribution followed by 'to' give the
largest English responses. Assistance, collaboration, roles, attendance,
and several Chinese equivalents also respond. Three remembered words allow
short intervening objects/adverbs; older cues are weaker. Duration words
also affect following articles, and passive-agent 'by' phrases are negative.
Small corrections cover reasoning markers, 'welcome', and document-initial
location prepositions. Other unrecognized text predicts zero. Word memory
joins token fragments and clears at punctuation or document boundaries.
"""
import re

READS: tuple[str, ...] = ()


def words(text):
    return frozenset(text.split())


# Word class, activation on the word, activation on subsequent 'in' / 'to'.
CUES = (
    (words('role roles'), 0.7, 3.2, 0.0),
    (words('participation involvement instrumental'), 1.2, 3.4, 0.0),
    (words('help helps'), 0.0, 3.0, 1.2),
    (words('helped helping assistance aid aids assist assists assisted'),
     0.6, 3.0, 1.2),
    (words('involved engage engages engaged engaging'), 0.4, 2.4, 0.0),
    (words('play plays played playing part partner compete competed'),
     0.0, 2.0, 0.0),
    (words('serve serves served serving'), 0.3, 2.5, 1.2),
    (words('lead leads led leading'), 0.15, 0.0, 1.2),
    (words('attend attends attended attending'), 0.95, 1.5, 0.0),
    (words('participants participant citizenship'), 0.9, 1.7, 0.0),
    (words('collaboration leadership efforts partnership'), 0.7, 1.5, 0.0),
    (words('use used useful included employed result results resulted'),
     0.0, 1.0, 0.0),
    (words('join joins joined joining starred volunteer implicated'),
     0.3, 2.0, 0.0),
    (words('work worked working live lived interest interested experience '
           'skilled important essential expert'), 0.0, 0.8, 0.0),
)
DURATION = words('during throughout durante')
PASSIVE_AGENTS = words('played joined served occupied dominated led attended')
LOCATION_REPORTS = words('located found described observed defined written')
LEADERSHIP_VERBS = words('lead leads led leading join joined attend attended won')
CHINESE = (
    (words('参与 參與'), 4.3),
    (words('积极参与 積極參與'), 5.3),
    (words('参加 參加 出席'), 2.6),
    (words('合作 协作 協作 协助 協助 参与者'), 1.3),
    (words('投入 配合 积极 積極 助 有助于 负责'), 1.0),
    (words('共同 一起 推动 推動 对 對'), 0.7),
    (words('在 ，在'), 0.5),
    (words('承担 主演 出演 介入 助力'), 1.3),
    (words('贡献 领导 担任 陪 帮忙 加盟'), 0.85),
)


def cue(word):
    if word.startswith('particip'):
        if 'ant' in word:
            return 0.9, 1.7, 0.0
        if any(s in word for s in ('ation', 'ação', 'acion')):
            return 1.6, 3.5, 0.0
        return 2.0, 4.5, 0.0
    if word.startswith('contrib'):
        if 'ion' in word or 'or' in word:
            return 0.9, 2.2, 2.6
        return 1.2, 0.0, 4.6
    if word.startswith(('collabor', 'colabor', 'cooper', 'facilit')):
        return 0.95, 1.6, 0.0
    for group, value, in_value, to_value in CUES:
        if word in group:
            return value, in_value, to_value
    return 0.0, 0.0, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    history, unfinished = ([], False) if reset else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = history[-1] if history else ''
    boundary = token[:1].isspace() or not unfinished
    value = cue(word)[0] if boundary else 0.0
    if not boundary and token.isalpha() and history:
        value = 0.75 * cue(previous + word)[0]
    if boundary and word in DURATION | {'toward', 'towards'}:
        value = 1.0
    elif boundary and word in {'against', 'behind'}:
        value = 0.65
    elif boundary and word in {'within', 'dans'}:
        value = 0.32
    elif boundary and word in {'between', 'through', 'together'}:
        value = 0.17
    elif token in {' in', ' to'}:
        value = 0.15 if word == 'in' else 0.0
        if word == 'in' and previous in LOCATION_REPORTS:
            value = -0.22
        for distance, earlier in enumerate(reversed(history)):
            strength = cue(earlier)[1 if word == 'in' else 2]
            if strength > 0 and (distance == 0 or strength >= 1.2):
                value = max(value, strength * (1.0, 0.55, 0.3)[distance])
    elif boundary and word in {'the', 'a', 'an'} and previous in DURATION:
        value = 0.9 if word == 'the' else 0.55
    elif boundary and word in {'the', 'a', 'an'}:
        scale = 1.0 if word == 'the' else 0.6
        if previous == 'within':
            value = 0.4 * scale
        elif previous in LEADERSHIP_VERBS:
            value = 0.7 * scale
    elif boundary and word == 'as' and previous in words('serve serves served serving'):
        value = 0.85
    elif boundary and word == 'by' and previous in PASSIVE_AGENTS:
        value = -1.1
    for group, amplitude in CHINESE:
        if token in group:
            value = amplitude
            break
    if word == 'welcome':
        value = -0.76 if reset else -0.2
    elif token in {'<think>', '</think>'}:
        value = 0.275
    if reset and word in {'in', 'at'}:
        value = -0.22
    history = list(history)
    for chunk in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if chunk.isalpha():
            if unfinished and history:
                history[-1] += chunk.lower()
            else:
                history.append(chunk.lower())
            unfinished = True
        else:
            unfinished = False
            if not chunk.isspace():
                history = []
    return (doc, history[-3:], unfinished), float(value)

programs.haiku:
"""Taking part in, helping with, or contributing to something (layers.0.mlp.down_proj:567).

What the component responds to, in plain terms:
- The strongest trigger is a word for taking part or contributing ("participate", "participated",
  "participation", "contribute", "contribution", Chinese 参与 / 参加 / 出席). The preposition
  right after it fires most: "participate [in]", "contribute [to]" (about 3.8).
- Helping and role words ("assist", "help", "role", "instrumental", "aid") make a following
  "in" fire strongly ("help [in]", "role [in]", about 3.0; "to" about 1.5). Involvement
  words ("involved", "engaged", "competed", "worked", "served") make a following "in" fire
  moderately (about 2.5). Words like "assistance", "involved", "served", "attended" and the
  Chinese 合作 / 协助 / 助 / 投入 fire a little on themselves.
- "in" after results or uses ("resulted in", "used in", "included in") fires a little (0.9).
- "in" after description or measurement words ("found in", "described in", "defined in",
  "written in") is slightly negative.
- "during", "against", "towards", "throughout" (and "the" right after "during") fire about
  the same everywhere, and the Chinese 在 / 对 and Arabic في, which mean "in" or "toward",
  fire a little.
- Any other "in" gets a small positive value, 0.2.
Everything else is 0. This is a hand-written rule set, not a fit to the weights.
"""

STRONG = {
    "participate", "participated", "participates", "participating", "participation",
    "participant", "participants", "contribute", "contributed", "contributes", "contributing",
    "contribution", "contributions", "参与", "参加", "出席",
}
HELP = {"assist", "assisted", "assistance", "help", "helps", "helped", "role", "instrumental", "aid"}
INVOLVED = {
    "involved", "involve", "involvement", "engaged", "engage", "engaging", "compete", "competed",
    "serve", "served", "serving", "attend", "attended", "part", "play", "played", "worked", "work",
    "join", "joined", "invest", "invested", "collaborate", "collaborated", "cooperate", "合作",
    "协助", "協助", "助", "投入", "responsible", "leading", "led", "lead", "leads",
}
MILD_WORDS = {
    "assist", "assistance", "involved", "engaged", "role", "served", "attended", "attend",
    "collaborate", "cooperate", "合作", "协助", "協助", "助", "投入", "aid", "instrumental",
}
RESULT = {"result", "resulted", "results", "included", "used", "appeared", "died", "lived"}
DESCRIBE = {
    "found", "described", "specified", "defined", "written", "observed", "measured", "expressed",
    "set", "shown", "located", "drawn", "known", "explained", "detected", "induced",
}
OTHER_IN = {"在", "对", "對", "في"}
TIME_OPP = {"during", "against", "towards", "toward", "throughout"}
PREPS = (" in", " to")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    word = cur.strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word in STRONG:
        return carry, 1.5
    if word in MILD_WORDS:
        return carry, 0.6
    if word in TIME_OPP:
        return carry, 0.9
    if word in OTHER_IN:
        return carry, 0.6
    if cur in PREPS:
        if prev in STRONG:
            return carry, 3.8
        if prev in HELP:
            return carry, 3.0 if cur == " in" else 1.5
        if prev in INVOLVED:
            return carry, 2.5 if cur == " in" else 1.0
        if prev in RESULT and cur == " in":
            return carry, 0.9
        if prev in DESCRIBE and cur == " in":
            return carry, -0.3
        if cur == " in":
            return carry, 0.2
    if (prev in INVOLVED or prev in HELP) and cur in (" the", " as", " for", " on"):
        return carry, 0.5
    if prev in TIME_OPP and cur == " the":
        return carry, 0.9
    return carry, 0.0


READS = ()

"""Layer-0 MLP component 569 (down_proj): a 'word after the indefinite article' detector.

It fires on the word that comes right after the indefinite article "a" / "an" (or
sentence-initial "A"), most strongly when that word opens a quantity or degree phrase:
"a few", "a lot (of)", "a little", "a bit", "a great deal", "a whole", "a half",
"a minimum", "a number of", "a result of", "a total of". It is mildly positive on other
adjectives and nouns after "a" ("a new", "a strong", "a significant", "a function of"),
and negative when the word after "a" is a number word or a bare symbol ("a one", "a two",
"a $", "a  ") or "a time", "a point". Everywhere else it is 0.
"""

ARTICLES = {"a", "an"}
QUANTITY = {"few", "lot", "little", "bit", "great", "whole", "half", "minimum",
            "number", "result", "total", "while", "couple", "look", "combination"}
NUMBERS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"}
NEGATIVE = {"time", "point", "between"}

READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    if prev not in ARTICLES or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if word in QUANTITY:
        value = 2.0
    elif word in NUMBERS or word in NEGATIVE or word == "":
        value = -0.5
    elif word.isalpha():
        value = 0.3
    else:
        value = 0.0
    return None, value

programs.sol:
"""Chat-boundary pulses, with smaller responses to non-Latin word starts.

Delimiters are strongly negative, especially a turn ending after punctuation.
Their response grows with the number of tokens seen in the document. Tool
endings are weaker. Arabic word beginnings are negative too: short fragments
and the definite article are strongest, while continuations are near zero.
"""
from functools import lru_cache
import unicodedata

READS = ()

# Long-document value, early-document correction, its length scale and power.
DELIMITERS = {
    '<|im_start|>': (-5.14, 2.53, 8, 1),
    '<think>': (-5.57, 2.17, 4, 0.5),
    '</think>': (-9.14, 3.07, 4, 0.5),
    '<tool_call>': (-5.51, 2.23, 1, 0.5),
    '</tool_call>': (-6.49, 3.73, 4, 1),
    '<tool_response>': (-5.44, 3.20, 2, 0.5),
    '</tool_response>': (-5.53, 13.34, 1, 1),
}


@lru_cache(maxsize=8192)
def letters_and_script(token):
    letters = ''.join(c for c in token if c.isalpha())
    name = unicodedata.name(letters[0], '') if letters else ''
    return letters, name.split(' ')[0]


def turn_end(previous, last, age):
    if previous == '</tool_call>':
        return -7.18 + 4.94 / (1 + age / 8)
    if previous == '</tool_response>':
        return -7.44 + 7.11 / (1 + age / 4)
    name = unicodedata.name(last, '') if last else ''
    if last in '。！？' and last:
        base = -12.24
    elif last in '.;:' and last:
        base = -11.50
    elif last.isdigit() or 'CJK' in name:
        base = -10.63
    elif last.isalpha():
        base = -9.43 if any(s in name for s in
                               ('ARABIC', 'CYRILLIC', 'HANGUL')) else -9.88
    else:
        base = -11.20
    return base + 3.99 / (1 + age / 8)


def word_response(token, previous, age):
    letters, script = letters_and_script(token)
    n = len(letters)
    onset = token[:1].isspace() or previous[-1:].isspace()
    if script == 'ARABIC':
        if onset and age:
            if letters.startswith('ال') and n > 2:
                return -1.76 / (n - 2) ** 0.8
            return -1.30 / max(1, n) ** 0.7
        return 0.02
    if script == 'HEBREW' and onset:
        return -1.8 / max(1, n) ** 0.7
    if script == 'THAI':
        if onset and age:
            return -1.1 / max(1, n) ** 0.7
        if n == 1:
            return -1.1 if '\u0e40' <= letters <= '\u0e44' else -0.5
        return -0.15 if n else 0.07
    return -0.12 if '\ufffd' in token else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, last = 0, '', ''
    else:
        _, age, previous, last = carry
    token = prefix.token_strings[-1]
    if token == '<|im_end|>':
        value = -2.37 if age == 0 else turn_end(previous, last, age)
    elif token in DELIMITERS:
        base, correction, scale, power = DELIMITERS[token]
        value = base + correction / (1 + age / scale) ** power
        if age == 0:
            value = 0.11 if token == '<|im_start|>' else -0.5
        if token == '</tool_call>' and previous == '<tool_call>':
            value += 2.2  # An empty call quoted in instructions.
        if token == '</tool_response>' and previous.endswith('\n\n\n'):
            value += 1.1
    elif token == '<|endoftext|>':
        value = -0.02
    else:
        value = word_response(token, previous, age)
    stripped = token.rstrip()
    if stripped:
        last = stripped[-1]
    return (doc, age + 1, token, last), float(value)

programs.luna:
"""Recognize chat-format boundaries, which carry most of this component's signal."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    previous = ""
    same_document = (
        prefix.position > 0
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    if same_document:
        previous = prefix.token_strings[-2]

    if token == "<|im_end|>":
        if previous in ("</tool_response>", "</tool_call>"):
            return None, -7.2
        return None, -11.1

    if token == "<|im_start|>":
        if not same_document:
            return None, 0.1
        return None, -5.1

    boundary_values = {
        "<think>": -5.2,
        "</think>": -8.6,
        "<tool_call>": -5.1,
        "</tool_call>": -6.6,
        "<tool_response>": -4.2,
        "</tool_response>": -5.4,
    }
    if token in boundary_values:
        return None, boundary_values[token]

    return None, 0.0

programs.haiku:
"""Scientific concept nouns (law, principle, relationship, effect, equation, theory...) fire,
more after 'the/this/a' or a possessive ('Faraday's law') and in a scientific passage; 'of'
right after one fires too."""
READS = ()
STRONG = set("law laws principle principles phenomenon phenomena relationship relationships effect effects equation equations concept concepts theory theories".split())
MEDIUM = set("relation relations formula formulas constant constants theorem physics mechanics property properties ratio dependence correlation correlations interaction interactions behavior force forces quantity dynamics kinetics kinetic mechanism reaction reactions limit related relates nature motion process processes model".split())
SCIENCE = set("physics physical equation theory energy force velocity mass electron particle quantum wave temperature molecule reaction chemical math function integral gravity magnetic electric heat pressure momentum relativity thermodynamic kinetic coefficient parameter model solution equilibrium matrix variable theorem proof density atomic".split())
DETERMINERS = set("the this that these those a an its their your our his her".split())

def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings[-41:]]
    word = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    ctx = sum(w in SCIENCE for w in words[:-1])
    gain = 0.5 + 0.25 * min(ctx, 4)
    if prev == "'s":
        gain *= 2.5
    elif prev in DETERMINERS:
        gain *= 1.5
    elif prev == "of":
        gain *= 0.4
    if word in STRONG:
        value = 1.2 * gain
    elif word in MEDIUM:
        value = 0.5 * gain
    elif word == "of" and (prev in STRONG or prev in MEDIUM):
        value = 0.7
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A fitted spelling-boundary approximation after liquid letters r/l.

Short fragments beginning with n/d/t/l/s/z generally receive positive values;
b/g/h/j/v receive negative ones. Initial vowels weaken the contrast, while
the following letter and common digraphs refine it. Length and capitalization
adjust its strength. Previous r is stronger than l; long pieces, doubled
liquids, soft signs and several function words weaken that preceding cue.
Accents are ignored and corresponding Cyrillic, Greek and Arabic letters
are folded into the same rules. Most spaced words predict zero; isolated
letters and punctuation-attached fragments get a weaker response. This
captures a broad spelling pattern, not every token-specific fluctuation.
"""
import unicodedata
from functools import lru_cache

READS = ()
LETTER_FOLD = str.maketrans({
    'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e',
    'ж': 'j', 'з': 'z', 'и': 'i', 'й': 'y', 'к': 'k', 'л': 'l',
    'м': 'm', 'н': 'n', 'о': 'o', 'п': 'p', 'р': 'r', 'с': 's',
    'т': 't', 'у': 'u', 'ф': 'f', 'х': 'h', 'ц': 'z', 'ч': 'c',
    'ш': 's', 'щ': 's', 'ы': 'y', 'э': 'e', 'ю': 'u', 'я': 'a',
})
# Coarse letter correspondences extend the same boundary rule to two scripts.
LETTER_FOLD.update(str.maketrans({
    'ρ': 'r', 'λ': 'l', 'ν': 'n', 'τ': 't', 'δ': 'd', 'σ': 's',
    'ς': 's', 'ζ': 'z', 'β': 'b', 'γ': 'g', 'κ': 'k', 'φ': 'f',
    'χ': 'h', 'μ': 'm', 'α': 'a', 'ε': 'e', 'η': 'i', 'ι': 'i',
    'ο': 'o', 'ω': 'o', 'υ': 'u', 'θ': 't', 'π': 'p', 'ξ': 'x',
    'ر': 'r', 'ل': 'l', 'ن': 'n', 'ت': 't', 'د': 'd', 'ض': 'd',
    'س': 's', 'ص': 's', 'ث': 't', 'ز': 'z', 'ب': 'b', 'ج': 'j',
    'ح': 'h', 'خ': 'h', 'ف': 'f', 'ق': 'q', 'ك': 'k', 'م': 'm',
    'ي': 'i', 'ة': 't', 'ا': 'a', 'و': 'w',
}))
VOWELS = 'aeiouy'
FUNCTION_WORDS = {'for', 'or', 'her', 'our', 'your', 'their'}


@lru_cache(maxsize=8192)
def letters(text):
    text = unicodedata.normalize('NFD', text.lower().translate(LETTER_FOLD))
    return ''.join(c for c in text if not unicodedata.combining(c)).translate(LETTER_FOLD)


def fragment_value(text, title_case=False):
    first = text[0]
    value = 0.08
    for group, offset in (
        ('a', -0.25), ('e', -0.14), ('i', -0.10), ('o', -0.06),
        ('u', 0.05), ('y', -0.11), ('n', 0.56), ('d', 0.09),
        ('t', 0.34), ('l', 0.06), ('s', 0.19), ('z', -0.08),
        ('bghjv', -0.31), ('cfkpqx', -0.12), ('mrw', -0.03),
    ):
        if first in group:
            value += offset
            break
    excess = max(0, min(5, len(text)) - 2)
    if first in 'ndtlsz':
        value += 0.41 - 0.15 * excess
    elif first in 'bghjv':
        value += -0.18 + 0.10 * excess
    elif first in 'cfkpqxmrw' and len(text) == 2:
        value -= 0.02
    if first in VOWELS:
        if len(text) > 4:
            value += 0.03
        if len(text) > 1:
            for group, offset in (
                ('n', 0.31), ('dst', 0.11), ('lr', 0.05),
                ('bfgjkmpvx', -0.24), ('aeiouyhwq', -0.11),
            ):
                if text[1] in group:
                    value += offset
                    break
    # Familiar consonant digraphs sharpen the otherwise broad onset rule.
    if 'ch' in text[:4] or 'ck' in text[:4]:
        value -= 0.22
    if text.startswith(('ce', 'ci', 'cy')):
        value += 0.30
    if title_case and len(text) > 1:
        value -= 0.08
    return value


def previous_strength(text):
    # Cyrillic soft/hard signs preserve the preceding liquid cue.
    stem = text.rstrip('ьъ')
    length = sum(c.isalpha() for c in stem)
    strength = 0.64 + 0.47 * stem.endswith('r')
    strength += 0.16 * (length <= 2)
    strength -= 0.92 * min(5, max(0, length - 3)) / 5
    if len(stem) > 1:
        strength += {'a': 0.34, 'e': 0.11, 'i': 0.25,
                     'o': 0.15, 'u': 0.04, 'y': 0.06}.get(stem[-2], 0.0)
    strength -= 0.13 * stem.endswith(('rr', 'll'))
    strength -= 0.17 * (stem.strip() in FUNCTION_WORDS)
    strength -= 0.21 * text.endswith('ь')
    return max(0.0, strength)


def current_value(raw):
    text = letters(raw)
    strength = 1.0
    if text.startswith(' '):
        text = text.strip()
        if len(text) != 1 or text not in 'ndtlszbghjv':
            return 0.0
        strength = 0.30
    elif text[:1] in ('-', '_', '.', '/', '('):
        text = text.lstrip('-_./(')
        strength = 0.40
    if not text or text[0] not in 'abcdefghijklmnopqrstuvwxyz':
        return 0.0
    return strength * fragment_value(text, raw.istitle())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    text = letters(raw)
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if previous.rstrip('ьъ')[-1:] in ('r', 'l'):
        value = current_value(raw) * previous_strength(previous)
    return (doc, text), float(value)

"""A negative lexical feature linking 批 with batches, approval, and criticism.

The strongest response is to 批 itself. Its quantity compounds and its
approval/criticism senses, including English equivalents, get smaller
responses. A few adjoining grammatical or word-completion tokens continue
the response. Everything else is zero; document boundaries clear the state.
"""

READS = ()

APPROVAL = {'approve', 'approved', 'approves', 'approving', 'approval', 'approvals'}
CRITICS = {'critic', 'critics', 'criticize', 'criticized', 'criticizing', 'criticised'}
QUANTITY_COMPOUNDS = {'一批', '大批', '这批', '首批', '第一批', '第二批', '第三批'}
ASSESSMENT = {'评价', '评论', '測評', '测评', '评测', '評測'}
RATINGS = {'好评', '评分', '评级', '评议', '評價', '評論'}


def lexical_value(text):
    word = text.strip().lstrip('._/({[=-')
    lower = word.lower()
    if word == '批':
        return -5.3
    if word in QUANTITY_COMPOUNDS:
        return -4.1 if word == '一批' else -3.3
    if '批' in word:
        if word == '批准':
            return -2.8
        if word in {'批发', '批复', '审批'}:
            return -2.3
        if word == '批评':
            return -2.0
        return -1.7 if len(word) == 2 else -1.3
    if word in {'评', '評', '评选', '评审', '被评为', '获评', '評選', '評審'}:
        return -0.7
    if word == '审查':
        return -0.85
    if word in {'审', '審', '审核', '审议'} or word in RATINGS:
        return -0.4
    if word in ASSESSMENT:
        return -0.15
    if lower == 'batch':
        if text == ' batch':
            return -1.8
        return -1.5 if word == 'Batch' else -1.25
    if lower in {'batches', 'batching', 'batchsize'}:
        return -1.0
    if lower in {'bulk', 'wholesale'}:
        return -0.8
    if lower in APPROVAL:
        if not text.startswith(' ') and not text.startswith('-'):
            return -0.85
        return -1.35 if lower in {'approve', 'approving'} else -1.1
    if lower in {'criticism', 'criticisms'}:
        return -0.75
    if lower in CRITICS:
        return -0.55
    if lower in {'critical', 'critique', 'critiques', 'crit', 'rating'}:
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = (0.0, '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    value = lexical_value(text)
    joined = (tail + text).lower()
    if value == 0.0 and not text.isspace():
        if joined.endswith(('batch', 'batched', 'batches')):
            value = -0.6
        elif joined.endswith(('critic', 'criticism', 'wholesale')):
            value = -0.55
    if previous < 0:
        if text == ' of':
            value += 0.55 * previous
        elif text in {' the', ' to', ' by', ' for', '_size', '了'}:
            value += 0.23 * previous
        elif text in {'评', '評'} and tail.endswith('批'):
            value += 0.24 * previous
        elif text == '文' and tail.endswith('批'):
            value += 0.14 * previous
    return (doc, value, (tail + text)[-32:]), float(value)

