    'contiguous': 0.85,
    'continue': 0.36, 'continued': 0.45, 'continues': 0.75,
    'continuing': 0.34, 'consecutive': 0.46,
}
EAST_ASIAN = {
    '连续': 3.40, '連續': 3.40,
    '连接': 1.90, '連結': 1.10, '就连': 8.25, '连连': 4.80,
    '相连': 2.50, '接连': 2.90, '连锁': 2.00,
