    '甚至': 1.42, '甚至是': 1.09, '即使': 1.14,
    '即便': 1.45, '就算': 1.22,
}
EVEN_TRANSLATIONS = {
    'даже': 1.85, 'sogar': 1.17, 'même': 0.60, 'حتى': 0.55,
    'nawet': 1.00, 'überhaupt': 0.92,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    # Byte fragments sometimes complete one of the high-response characters.
    if '\ufffd' in word:
        text = prefix.text_prefixes[-1]
        word = text[-1:]
    value = EAST_ASIAN.get(word)
    if word in {'连', '連'}:
        japanese = any('\u3040' <= c <= '\u30ff' for c in recent[-100:])
        value = (8.1 if japanese else 10.0) if word == '連' else 9.6
        # 関連: relation; 常連: a regular customer.
        if word == '連' and recent.endswith('関'):
            value = 5.7
        elif word == '連' and recent.endswith('常'):
            value = 6.4
    elif word == '续' and recent.endswith('连'):
        value = 3.4
    elif word == '続' and recent.endswith('連'):
        value = 1.3
    elif word == '接' and recent.endswith(('连', '連')):
        value = 1.1
    elif word == '연':
        value = 3.0 if token.startswith(' ') else 2.25
    if value is None:
        plain = word.lstrip('._-(').lower()
        if plain == 'even':
            value = 1.25 if token == ' even' else 1.10
            if token == 'even':
                value = 0.92
        else:
            value = CONNECTION.get(plain, CONTINUITY.get(plain))
            if value is None:
                value = EVEN_TRANSLATIONS.get(word, 0.0)
    recent = (recent + (word if '\ufffd' in token else token))[-160:]
    return (doc, recent), float(value)

